-- Penandaan miskonsepsi pada pengecoh soal Bahasa Inggris SMA.
-- Sumber: supabase/seed/tka-bahasa-inggris-sma-miskonsepsi.map.json
-- Dihasilkan oleh scripts/generate-misconception-tags.mjs. Aman dijalankan ulang.
--
-- 90 definisi miskonsepsi, 110 soal, 379 pengecoh dan pernyataan ditandai.
begin;

insert into public.misconceptions (id, label, description, insight) values
  ('mis-eng-exp-001', 'Mencocokkan kata tanpa memeriksa maknanya', 'Memilih jawaban karena mengulang kata dari bacaan meskipun keseluruhan pernyataannya tidak didukung.', 'Periksa seluruh isi pilihan, bukan hanya kata yang sama dengan bacaan.'),
  ('mis-eng-exp-002', 'Mengambil rincian dari bagian yang berdekatan', 'Memilih rincian yang benar tetapi berasal dari kalimat lain sehingga tidak menjawab yang ditanyakan.', 'Cocokkan rincian yang diminta dengan kalimat atau bagian yang tepat.'),
  ('mis-eng-exp-003', 'Menganggap sebagian syarat sudah lengkap', 'Memakai satu bagian dari syarat yang terdiri atas beberapa bagian dan melewatkan sisanya.', 'Periksa setiap bagian syarat pada pilihan terhadap isi bacaan.'),
  ('mis-eng-exp-004', 'Memilih hal yang masuk akal tetapi tidak disebutkan', 'Memilih informasi yang terdengar wajar di kehidupan nyata meskipun tidak dinyatakan bacaan.', 'Untuk soal informasi tersurat, jawaban harus punya bukti langsung di dalam bacaan.'),
  ('mis-eng-exp-005', 'Mengelompokkan berdasarkan dugaan sendiri', 'Mengelompokkan sesuatu memakai pengetahuan luar, bukan kategori yang dijelaskan bacaan.', 'Kelompokkan hanya berdasarkan ciri yang disebutkan bacaan.'),
  ('mis-eng-exp-006', 'Keliru membedakan dua kategori yang berdekatan', 'Menukar dua kategori karena keduanya memiliki tujuan atau ciri yang mirip.', 'Tentukan lebih dahulu ciri pembeda tiap kategori sebelum mengelompokkan.'),
  ('mis-eng-exp-007', 'Menukar pelaku dengan tindakannya', 'Menghubungkan tindakan atau tanggung jawab kepada orang atau pihak yang salah.', 'Telusuri siapa yang melakukan setiap tindakan yang disebutkan bacaan.'),
  ('mis-eng-exp-008', 'Menukar urutan waktu kejadian', 'Tertukar antara yang terjadi sebelum, saat, dan sesudah suatu peristiwa.', 'Gunakan penanda waktu dan kata urutan yang ada di bacaan.'),
  ('mis-eng-exp-009', 'Melewatkan kata not, only, dan except', 'Melewatkan kata pembatas atau pengecualian sehingga maknanya terbalik.', 'Perhatikan kata pembatas dan kata pertentangan dengan teliti.'),
  ('mis-eng-exp-010', 'Menambah pilihan yang hanya berkaitan dengan topik', 'Menandai pilihan tambahan karena masih setopik walaupun tidak didukung bacaan.', 'Pada soal jawaban ganda, uji setiap pilihan satu per satu.'),
  ('mis-eng-sum-001', 'Menganggap rincian kecil sebagai gagasan utama', 'Memperlakukan contoh, angka, atau rincian pendukung sebagai gagasan pokok.', 'Bedakan gagasan pokok sebuah bagian dari contoh yang memperjelasnya.'),
  ('mis-eng-sum-002', 'Merangkum hanya satu bagian teks', 'Meringkas hanya satu paragraf dari teks yang terdiri atas beberapa paragraf.', 'Ringkasan yang baik mewakili keseluruhan teks, bukan satu bagian saja.'),
  ('mis-eng-sum-003', 'Menambahkan simpulan sendiri ke dalam ringkasan', 'Menambahkan simpulan atau penilaian yang tidak dinyatakan teks.', 'Ringkasan harus setia pada informasi yang dinyatakan teks, tanpa tambahan penilaian.'),
  ('mis-eng-sum-004', 'Mengubah urutan langkah atau peristiwa', 'Menukar urutan tahap atau peristiwa sehingga susunan teks berubah.', 'Pertahankan urutannya bila teks memang disusun menurut tahapan atau waktu.'),
  ('mis-eng-sum-005', 'Mempertahankan terlalu banyak contoh', 'Menyimpan banyak contoh tetapi menghilangkan gagasan umum yang diwakilinya.', 'Padatkan contoh menjadi gagasan umum yang diwakilinya.'),
  ('mis-eng-sum-006', 'Membalik sebab dengan akibat', 'Menukar sebab dengan akibatnya ketika menyusun kerangka atau ringkasan.', 'Telusuri keadaan mana yang menghasilkan akibat mana.'),
  ('mis-eng-sum-007', 'Membuat ringkasan lebih luas daripada teksnya', 'Menyatakan klaim teks secara lebih luas atau lebih kuat daripada aslinya.', 'Pertahankan batas dan syarat yang disebutkan teks aslinya.'),
  ('mis-eng-sum-008', 'Memilih judul, bukan ringkasan', 'Memilih label topik yang kabur tanpa pengembangan penting dari teksnya.', 'Ringkasan memerlukan pesan utama beserta pengembangannya, bukan hanya label topik.'),
  ('mis-eng-sum-009', 'Menjadikan simpulan akhir sebagai seluruh ringkasan', 'Memakai hanya saran atau hasil akhir sebagai keseluruhan ringkasan.', 'Sertakan keadaan atau alasan yang menuntun ke simpulan itu.'),
  ('mis-eng-sum-010', 'Menempatkan rincian sederajat dengan bagian utama', 'Menempatkan rincian pendukung pada tingkat yang sama dengan bagian utama.', 'Susun bertingkat: gagasan utama lebih dahulu, rinciannya di bawahnya.'),
  ('mis-eng-syn-001', 'Menyimpulkan hanya dari satu sumber', 'Menjawab soal gabungan dua sumber dengan memakai satu sumber saja.', 'Periksa lebih dahulu sumbangan tiap sumber sebelum menarik simpulan.'),
  ('mis-eng-syn-002', 'Menganggap dua pernyataan setopik sudah sepakat', 'Menganggap dua pernyataan yang berkaitan menyampaikan klaim yang sama.', 'Bedakan topik yang sama dari kesepakatan isi yang sebenarnya.'),
  ('mis-eng-syn-003', 'Menganggap penekanan berbeda sebagai pertentangan', 'Menyimpulkan kedua sumber saling bertentangan hanya karena penekanannya berbeda.', 'Dua sumber dapat saling melengkapi meskipun tidak menyatakan hal yang sama.'),
  ('mis-eng-syn-004', 'Menghubungkan dua sumber tanpa dasar', 'Menambahkan hubungan antarsumber yang tidak ditopang oleh keduanya.', 'Setiap bagian simpulan gabungan harus dapat ditelusuri ke informasi yang diberikan.'),
  ('mis-eng-syn-005', 'Melebarkan cakupan simpulan', 'Menyatakan simpulan lebih luas atau lebih mutlak daripada isi sumbernya.', 'Pertahankan batas yang dinyatakan sumbernya; jangan menambah kata semua, selalu, atau satu-satunya.'),
  ('mis-eng-syn-006', 'Menukar isi antarsumber', 'Menyebut informasi berasal dari sumber yang salah atau menukar perannya.', 'Catat informasi mana yang berasal dari sumber mana sebelum menjawab.'),
  ('mis-eng-syn-007', 'Membiarkan satu rincian menguasai simpulan', 'Menyusun simpulan dari satu rincian yang menonjol saja.', 'Simpulan gabungan harus mewakili gambaran keseluruhan, bukan satu rincian yang menonjol.'),
  ('mis-eng-syn-008', 'Memberi saran tanpa syaratnya', 'Memberi saran tanpa menyebut keadaan yang membuat saran itu berlaku.', 'Saran perlu menyebut keadaan yang membuat saran itu berlaku.'),
  ('mis-eng-syn-009', 'Terjebak kata yang sama pada kedua sumber', 'Menganggap dua sumber sepakat karena memakai kata yang sama.', 'Kata yang sama belum berarti maksudnya sama; periksa pernyataan selengkapnya.'),
  ('mis-eng-syn-010', 'Mengganti isi sumber dengan pengetahuan sendiri', 'Menjawab dengan pengetahuan di luar sumber yang disediakan.', 'Jawaban harus bertumpu pada isi sumber yang diberikan, bukan pengetahuan di luarnya.'),
  ('mis-eng04-01', 'Menyebut topik, bukan gagasan utamanya', 'Memilih topik yang luas, bukan apa yang penulis katakan tentang topik itu.', 'Gagasan utama menyatakan apa yang penulis katakan tentang topiknya, bukan topiknya saja.'),
  ('mis-eng04-02', 'Menjadikan satu rincian sebagai gagasan utama', 'Menaikkan satu rincian yang benar menjadi gagasan utama teks.', 'Rincian yang benar belum tentu gagasan utama; cari gagasan yang menaungi seluruh teks.'),
  ('mis-eng04-03', 'Menyimpulkan lebih kuat daripada buktinya', 'Membuat simpulan lebih luas atau lebih tegas daripada bukti yang tersedia.', 'Pertahankan batas buktinya; hindari kata semua, selalu, dan seharusnya bila teks tidak menyatakannya.'),
  ('mis-eng04-04', 'Memakai dugaan dari luar teks', 'Memakai anggapan dari luar teks, bukan petunjuk yang tersedia di dalamnya.', 'Gunakan petunjuk di dalam teks, bukan hal yang biasa terjadi di luar teks.'),
  ('mis-eng04-05', 'Menukar tujuan penulisan dengan isi tulisan', 'Menyebut apa yang dibahas teks, bukan alasan teks itu ditulis.', 'Tujuan penulisan menjawab mengapa teks ditulis, bukan apa yang dibahasnya.'),
  ('mis-eng04-06', 'Menentukan sasaran pembaca dari topiknya saja', 'Menyimpulkan sasaran pembaca hanya dari topik teks.', 'Sasaran pembaca terlihat dari cara teks menjelaskan dan siapa yang dibantunya.'),
  ('mis-eng04-07', 'Memilih informasi berkaitan yang tidak memperkuat', 'Memilih informasi yang masih berkaitan tetapi tidak memperkuat gagasannya.', 'Bukti pendukung harus membuat gagasannya lebih kuat, bukan hanya setopik.'),
  ('mis-eng04-08', 'Memilih rincian yang justru melemahkan', 'Memilih rincian yang melemahkan alasan yang sedang dibangun teks.', 'Periksa apakah rincian yang dipilih mendukung atau justru melawan gagasan itu.'),
  ('mis-eng04-09', 'Mengubah pesan cerita menjadi aturan mutlak', 'Mengubah pesan yang berlaku pada keadaan tertentu menjadi aturan untuk semua keadaan.', 'Pesan cerita berlaku pada keadaannya; hindari mengubahnya menjadi aturan untuk semua hal.'),
  ('mis-eng04-10', 'Menyimpulkan dari satu petunjuk saja', 'Memakai satu kalimat atau frasa dan mengabaikan bukti lain di dalam teks.', 'Kumpulkan beberapa petunjuk yang searah sebelum menyimpulkan.'),
  ('mis-eng05-01', 'Memilih kelanjutan yang mungkin tetapi jauh dari arah teks', 'Memilih kelanjutan yang mungkin terjadi tetapi hubungannya lemah dengan arah teks.', 'Pilih kelanjutan yang menyambung arah dan tujuan teks, bukan yang sekadar mungkin terjadi.'),
  ('mis-eng05-02', 'Membalik urutan sebab, persiapan, tindakan, dan hasil', 'Menukar urutan sebab, persiapan, tindakan, atau hasil dalam rangkaian yang disimpulkan.', 'Telusuri urutan yang dinyatakan teks: apa yang menyiapkan apa, dan apa yang menghasilkan apa.'),
  ('mis-eng05-03', 'Memprediksi hal baru yang tidak berhubungan', 'Memilih kelanjutan yang memunculkan persoalan yang tidak berkaitan.', 'Kelanjutan harus tetap pada persoalan yang sedang dibahas teks.'),
  ('mis-eng05-04', 'Menganggap prediksi yang wajar sebagai kepastian', 'Memperlakukan prediksi yang masuk akal sebagai hal yang pasti terjadi.', 'Prediksi tetap berupa kemungkinan; hindari kata pasti, semua, dan langsung.'),
  ('mis-eng05-05', 'Membandingkan lewat kemiripan yang sepele', 'Memilih kemiripan kecil, bukan perbandingan yang bermakna.', 'Bandingkan hal yang benar-benar penting bagi kedua sisi, bukan kemiripan kecil.'),
  ('mis-eng05-06', 'Membuat perbedaan yang tidak dinyatakan teks', 'Menyimpulkan perbedaan yang tidak ditopang teks.', 'Perbedaan harus ada buktinya di dalam teks, bukan disimpulkan sendiri.'),
  ('mis-eng05-07', 'Menjelaskan satu sisi saja', 'Menggambarkan satu hal saja padahal yang diminta membandingkan keduanya.', 'Perbandingan menyebut kedua sisi, bukan menggambarkan satu sisi saja.'),
  ('mis-eng05-08', 'Mengubah perbedaan bersyarat menjadi mutlak', 'Mengubah perbedaan yang berlaku pada keadaan tertentu menjadi klaim selalu atau tidak pernah.', 'Pertahankan syaratnya; hindari mengubah kadang menjadi selalu atau tidak pernah.'),
  ('mis-eng05-09', 'Membiarkan satu detail menentukan seluruh perbandingan', 'Memakai satu detail mencolok untuk menyimpulkan seluruh perbandingan.', 'Satu detail mencolok tidak cukup untuk menyimpulkan perbandingan keseluruhan.'),
  ('mis-eng05-10', 'Menganggap urutan penyebutan sebagai urutan kejadian', 'Menganggap urutan penyebutan dalam teks selalu sama dengan urutan kejadiannya.', 'Urutan penyebutan dalam teks belum tentu urutan kejadiannya.'),
  ('mis-eng06-01', 'Menganggap dua hal yang terjadi bersamaan sebagai sebab-akibat', 'Menganggap dua kejadian yang muncul bersamaan membuktikan yang satu menyebabkan yang lain.', 'Kejadian yang muncul bersamaan belum membuktikan yang satu menyebabkan yang lain.'),
  ('mis-eng06-02', 'Menjadikan akibat sebagai penyebabnya', 'Memperlakukan hasil sebagai penyebab dari keadaan yang justru menghasilkannya.', 'Telusuri keadaan mana yang lebih dahulu ada dan menghasilkan keadaan berikutnya.'),
  ('mis-eng06-03', 'Menganggap satu hal sebagai penyebab tunggal', 'Mengabaikan beberapa faktor yang berperan dan memilih satu rincian sebagai penyebab seluruhnya.', 'Periksa apakah ada beberapa faktor yang bersama-sama menimbulkan keadaan itu.'),
  ('mis-eng06-04', 'Memakai penyebab dari luar teks', 'Memakai penjelasan yang masuk akal tetapi tidak ditopang bacaan.', 'Penyebab yang dipilih harus disebutkan atau ditunjukkan bacaan, bukan dugaan sendiri.'),
  ('mis-eng06-05', 'Berhenti pada akibat yang langsung terlihat', 'Menyebut akibat langsung tetapi melewatkan akibat lanjutan yang lebih penting.', 'Cari juga akibat lanjutan yang lebih penting, bukan hanya akibat yang langsung terjadi.'),
  ('mis-eng06-06', 'Menyimpulkan watak dari satu tindakan', 'Menyimpulkan watak tokoh dari satu tindakan tanpa memeriksa pola tindakannya.', 'Periksa pola tindakan tokoh di beberapa bagian sebelum menyimpulkan wataknya.'),
  ('mis-eng06-07', 'Menganggap perasaan sesaat sebagai watak', 'Menukar perasaan yang muncul sesaat dengan watak yang menetap.', 'Bedakan perasaan yang muncul sesaat dari watak yang menetap.'),
  ('mis-eng06-08', 'Menilai tokoh secara mutlak dari bukti terbatas', 'Mengubah bukti yang terbatas menjadi penilaian yang mutlak, baik positif maupun negatif.', 'Bukti yang terbatas hanya mendukung simpulan yang terbatas, bukan penilaian mutlak.'),
  ('mis-eng06-09', 'Mengikuti ucapan tokoh dan mengabaikan tindakannya', 'Menerima ucapan tokoh dan melewatkan bukti tindakan yang lebih kuat atau berlawanan.', 'Bila ucapan dan tindakan tokoh berbeda, tindakannya adalah bukti yang lebih kuat.'),
  ('mis-eng06-10', 'Menilai watak hanya dari berhasil atau gagalnya', 'Menyimpulkan watak tokoh hanya dari berhasil atau tidaknya hasil akhir.', 'Watak terlihat dari cara tokoh bertindak, bukan dari hasil akhirnya.'),
  ('mis-eng07-01', 'Memilih akhir yang paling dramatis', 'Memilih akhir yang paling mengejutkan, bukan yang paling ditopang petunjuk cerita.', 'Pilih akhir yang paling ditopang petunjuk cerita, bukan yang paling mengejutkan.'),
  ('mis-eng07-02', 'Memilih akhir yang paling diinginkan', 'Memilih akhir yang terasa paling menyenangkan meskipun teks tidak menopangnya.', 'Akhir cerita ditentukan petunjuk teks, bukan oleh apa yang terasa paling menyenangkan.'),
  ('mis-eng07-03', 'Memprediksi dari satu petunjuk saja', 'Memprediksi dari satu rincian dan mengabaikan jalan cerita secara keseluruhan.', 'Gabungkan beberapa petunjuk dari keseluruhan cerita sebelum memprediksi.'),
  ('mis-eng07-04', 'Memprediksi tindakan yang bertentangan dengan watak tokoh', 'Memprediksi tindakan yang berlawanan dengan keputusan tokoh sebelumnya.', 'Prediksi harus sejalan dengan keputusan yang sudah diambil tokoh sebelumnya.'),
  ('mis-eng07-05', 'Memunculkan kejadian baru yang tidak disiapkan cerita', 'Memunculkan orang, aturan, kecelakaan, atau penyelesaian yang tidak dipersiapkan cerita.', 'Jangan menambah tokoh, aturan, atau kebetulan yang tidak dipersiapkan cerita.'),
  ('mis-eng07-06', 'Memilih akhir yang tidak menyelesaikan masalah utamanya', 'Memilih akhir yang tidak menjawab persoalan pokok yang belum selesai.', 'Akhir cerita harus menjawab persoalan pokok yang belum selesai.'),
  ('mis-eng07-07', 'Mengubah kemungkinan menjadi kepastian', 'Mengubah hasil yang mungkin terjadi menjadi hasil yang mutlak atau berlebihan.', 'Prediksi tetap berupa kemungkinan; hindari kata selalu, tidak pernah, dan pasti.'),
  ('mis-eng07-08', 'Memprediksi tokoh kembali ke keadaan awalnya', 'Memprediksi tokoh kembali ke keadaan awal meskipun sudah ada perkembangan.', 'Perkembangan yang sudah terjadi pada tokoh tidak hilang begitu saja.'),
  ('mis-eng07-09', 'Menganggap kejadian berikutnya sebagai penyelesaian', 'Menganggap kejadian kecil berikutnya sudah menyelesaikan seluruh persoalan.', 'Kejadian kecil berikutnya belum tentu menyelesaikan seluruh persoalan.'),
  ('mis-eng07-10', 'Memilih akhir yang memberi ganjaran atau hukuman', 'Memilih akhir karena tokoh layak diberi ganjaran atau hukuman, bukan karena buktinya.', 'Akhir cerita mengikuti petunjuk teks, bukan rasa keadilan pembaca.'),
  ('mis-eng08-01', 'Menganggap yang mungkin terjadi sudah terbukti', 'Memperlakukan kejadian yang masuk akal sebagai fakta yang sudah dipastikan.', 'Kejadian yang wajar belum berarti benar-benar terjadi; cari pernyataan yang menopangnya.'),
  ('mis-eng08-02', 'Menganggap yang tidak dikenal pasti mustahil', 'Menolak sebuah kejadian hanya karena belum dikenal pembacanya.', 'Sesuatu tidak menjadi mustahil hanya karena belum dikenal pembacanya.'),
  ('mis-eng08-03', 'Menganggap teknologi dapat melakukan apa saja', 'Menganggap sebuah alat digital dapat bekerja melampaui kemampuan yang dijelaskan bacaan.', 'Batasi kemampuan alat pada yang dijelaskan bacaan.'),
  ('mis-eng08-04', 'Menganggap satu detail nyata menjamin seluruh cerita', 'Memakai satu detail yang masuk akal untuk membenarkan seluruh isi bacaan.', 'Satu detail yang masuk akal tidak membenarkan seluruh isi bacaan.'),
  ('mis-eng08-05', 'Menganggap pendapat sebagai fakta', 'Memperlakukan pendapat, penilaian, atau ramalan sebagai informasi yang sudah diperiksa.', 'Pendapat, penilaian, dan ramalan tidak sama dengan informasi yang dapat diperiksa.'),
  ('mis-eng08-06', 'Menganggap fakta sebagai pendapat', 'Memperlakukan pernyataan yang dapat diukur atau diperiksa sebagai pendapat pribadi.', 'Pernyataan yang dapat diukur atau diperiksa adalah fakta, meskipun terdengar seperti pendapat.'),
  ('mis-eng08-07', 'Menganggap pernyataan orang lain otomatis fakta', 'Menganggap sesuatu menjadi fakta karena ada orang atau unggahan yang menyatakannya.', 'Sebuah pernyataan tidak menjadi fakta hanya karena seseorang atau sebuah unggahan menyatakannya.'),
  ('mis-eng08-08', 'Menganggap angka menjamin kebenaran', 'Menganggap klaim yang memuat angka otomatis dapat dipercaya.', 'Angka tetap perlu diperiksa asalnya, cara pengukurannya, dan pembandingnya.'),
  ('mis-eng08-09', 'Menyimpulkan terlalu luas dari bukti terbatas', 'Memakai bukti yang terbatas untuk simpulan yang berlaku untuk semua.', 'Bukti yang terbatas hanya mendukung simpulan yang terbatas.'),
  ('mis-eng08-10', 'Menganggap bahasa yang meyakinkan sebagai bukti', 'Memperlakukan kata yang persuasif atau emosional sebagai bukti sebuah klaim.', 'Kata yang persuasif atau emosional bukan bukti; carilah datanya.'),
  ('mis-eng09-01', 'Menganggap satu sumber terbatas sudah cukup', 'Menganggap satu sumber yang terbatas cukup untuk simpulan yang luas.', 'Simpulan yang luas memerlukan lebih dari satu sumber atau lebih dari satu ukuran.'),
  ('mis-eng09-02', 'Menerima klaim karena sumbernya terdengar berwibawa', 'Menganggap klaim sahih hanya karena nama sumbernya terdengar berwibawa.', 'Nilai isi dan buktinya, bukan seberapa berwibawa nama sumbernya.'),
  ('mis-eng09-03', 'Menganggap dua sumber yang sepakat sebagai bukti pasti', 'Menganggap kesepakatan antarsumber sebagai bukti pasti meskipun keduanya terbatas.', 'Dua sumber dapat sepakat dan tetap sama-sama memiliki keterbatasan.'),
  ('mis-eng09-04', 'Menganggap dua sumber yang berbeda sama-sama salah', 'Menganggap laporan yang berbeda membuat kedua sumber tidak berguna.', 'Perbedaan penekanan tidak membuat kedua sumber tidak berguna.'),
  ('mis-eng09-05', 'Melewatkan keterangan yang diperlukan untuk membaca angkanya', 'Menerima klaim tanpa memperhatikan keterangan yang diperlukan untuk menafsirkannya.', 'Periksa apa yang diukur, siapa yang diukur, dan pembandingnya sebelum menerima angka.'),
  ('mis-eng09-06', 'Menganggap data yang lebih banyak selalu lebih baik', 'Menganggap jumlah data yang lebih besar otomatis lebih sahih.', 'Banyaknya data tidak menjamin mutunya; cara pengumpulannya juga menentukan.'),
  ('mis-eng09-07', 'Menganggap pengalaman satu orang mewakili semua', 'Memberlakukan pengalaman satu orang untuk kelompok yang lebih luas.', 'Pengalaman satu orang hanya menggambarkan dirinya, bukan seluruh kelompok.'),
  ('mis-eng09-08', 'Menganggap dua perubahan yang bersamaan saling menyebabkan', 'Menganggap dua perubahan yang terjadi bersamaan membuktikan yang satu menyebabkan yang lain.', 'Perubahan yang terjadi bersamaan belum membuktikan hubungan sebab-akibat.'),
  ('mis-eng09-09', 'Memilih tambahan informasi yang tidak menjawab keraguannya', 'Memilih informasi tambahan yang tidak menyentuh bagian yang masih belum pasti.', 'Informasi tambahan berguna bila menjawab bagian yang masih belum pasti.'),
  ('mis-eng09-10', 'Membaca simpulan berhati-hati sebagai simpulan mutlak', 'Mengabaikan kata pembatas sehingga simpulan yang terbatas dibaca sebagai mutlak.', 'Perhatikan kata mungkin, sebagian, dan cenderung; simpulannya memang dibatasi.')
on conflict (id) do update set
  label = excluded.label,
  description = excluded.description,
  insight = excluded.insight;

update public.questions set options = '[{"key":"A","text":"<p>asking AI to suggest several possible topics before beginning a project</p>","misconceptionId":"mis-eng-exp-006"},{"key":"B","text":"<p>asking AI to identify unclear sentences in a draft the student has written</p>"},{"key":"C","text":"<p>asking AI to produce the final response for an assessed classroom assignment</p>","misconceptionId":"mis-eng-exp-009"},{"key":"D","text":"<p>asking AI to store a private message so it can be used in a later task</p>","misconceptionId":"mis-eng-exp-009"},{"key":"E","text":"<p>asking AI to decide whether the teacher''s instructions should be followed</p>","misconceptionId":"mis-eng-exp-007"}]'::jsonb, updated_at = now() where id = 'tka-eng01-auth-001';
update public.questions set options = '[{"key":"A","text":"<p>Check important factual claims with reliable sources.</p>"},{"key":"B","text":"<p>Enter personal contact details when a prompt needs more context.</p>","misconceptionId":"mis-eng-exp-009"},{"key":"C","text":"<p>Follow the teacher''s instructions about reporting AI use.</p>"},{"key":"D","text":"<p>Keep passwords and private messages out of AI prompts.</p>"},{"key":"E","text":"<p>Use AI-generated answers unchanged when they sound confident.</p>","misconceptionId":"mis-eng-exp-009"}]'::jsonb, updated_at = now() where id = 'tka-eng01-auth-002';
update public.questions set statements = '[{"id":"A","text":"<p>Ask for a simpler explanation of a difficult concept.</p>","correctCategoryKey":"learning","misconceptionId":"mis-eng-exp-006"},{"id":"B","text":"<p>Create a rough outline before writing the text independently.</p>","correctCategoryKey":"planning","misconceptionId":"mis-eng-exp-006"},{"id":"C","text":"<p>Ask which sentences in an existing draft may be unclear.</p>","correctCategoryKey":"checking","misconceptionId":"mis-eng-exp-006"}]'::jsonb, updated_at = now() where id = 'tka-eng01-auth-003';
update public.questions set options = '[{"key":"A","text":"<p>Post the image later after changing the location setting on the account.</p>","misconceptionId":"mis-eng-exp-006"},{"key":"B","text":"<p>Choose another photo or edit the image so the friend cannot be identified.</p>"},{"key":"C","text":"<p>Keep the original photo but limit comments from people outside the account.</p>","misconceptionId":"mis-eng-exp-004"},{"key":"D","text":"<p>Ask another friend to decide whether the image is suitable for posting.</p>","misconceptionId":"mis-eng-exp-007"},{"key":"E","text":"<p>Remove the place tag and publish the original image without further changes.</p>","misconceptionId":"mis-eng-exp-006"}]'::jsonb, updated_at = now() where id = 'tka-eng01-auth-004';
update public.questions set statements = '[{"id":"A","text":"<p>Crop a visible house number from the background.</p>","correctCategoryKey":"image","misconceptionId":"mis-eng-exp-006"},{"id":"B","text":"<p>Review who can view the specific post.</p>","correctCategoryKey":"audience","misconceptionId":"mis-eng-exp-006"},{"id":"C","text":"<p>Tell visible friends where the photo will be posted.</p>","correctCategoryKey":"permission","misconceptionId":"mis-eng-exp-006"},{"id":"D","text":"<p>Wait until leaving a place before sharing its tag.</p>","correctCategoryKey":"location","misconceptionId":"mis-eng-exp-006"}]'::jsonb, updated_at = now() where id = 'tka-eng01-auth-005';
update public.questions set options = '[{"key":"A","text":"<p>a house number visible behind the main subject</p>"},{"key":"B","text":"<p>the number of likes received by an older post</p>","misconceptionId":"mis-eng-exp-010"},{"key":"C","text":"<p>a friend who can be clearly identified in the image</p>"},{"key":"D","text":"<p>location information attached to or added to the post</p>"},{"key":"E","text":"<p>the amount of storage space remaining on the phone</p>","misconceptionId":"mis-eng-exp-010"}]'::jsonb, updated_at = now() where id = 'tka-eng01-auth-006';
update public.questions set statements = '[{"id":"A","text":"<p>desk fan</p>","correctCategoryKey":"quick","misconceptionId":"mis-eng-exp-006"},{"id":"B","text":"<p>backpack with a loose strap</p>","correctCategoryKey":"repair","misconceptionId":"mis-eng-exp-006"},{"id":"C","text":"<p>umbrella with damaged ribs</p>","correctCategoryKey":"repair","misconceptionId":"mis-eng-exp-006"},{"id":"D","text":"<p>bicycle lamp with battery-compartment damage</p>","correctCategoryKey":"specialist","misconceptionId":"mis-eng-exp-006"}]'::jsonb, updated_at = now() where id = 'tka-eng01-auth-007';
update public.questions set options = '[{"key":"A","text":"<p>The owner asked the volunteers to stop working on the lamp.</p>","misconceptionId":"mis-eng-exp-004"},{"key":"B","text":"<p>The team found damage inside the lamp''s battery compartment.</p>"},{"key":"C","text":"<p>The repair table had no space for another electronic object.</p>","misconceptionId":"mis-eng-exp-004"},{"key":"D","text":"<p>The volunteers had already repaired eleven items that afternoon.</p>","misconceptionId":"mis-eng-exp-002"},{"key":"E","text":"<p>The club planned to publish a new list before the next event.</p>","misconceptionId":"mis-eng-exp-002"}]'::jsonb, updated_at = now() where id = 'tka-eng01-auth-008';
update public.questions set statements = '[{"id":"A","text":"<p>marks possible answers in a reference book with sticky notes</p>","correctCategoryKey":"maya","misconceptionId":"mis-eng-exp-007"},{"id":"B","text":"<p>downloads needed files before working on coding exercises</p>","correctCategoryKey":"faris","misconceptionId":"mis-eng-exp-007"},{"id":"C","text":"<p>reviews digital flashcards during the final part of the hour</p>","correctCategoryKey":"nina","misconceptionId":"mis-eng-exp-007"},{"id":"D","text":"<p>writes questions about ideas that are still unclear</p>","correctCategoryKey":"maya","misconceptionId":"mis-eng-exp-007"}]'::jsonb, updated_at = now() where id = 'tka-eng01-auth-009';
update public.questions set options = '[{"key":"A","text":"<p>Group discussions are moved to another area during quiet hour.</p>"},{"key":"B","text":"<p>Faris listens to music through headphones while doing coding exercises.</p>","misconceptionId":"mis-eng-exp-009"},{"key":"C","text":"<p>Nina waits until quiet hour ends before practising speaking.</p>"},{"key":"D","text":"<p>Every student must use the same study method from four to five.</p>","misconceptionId":"mis-eng-exp-009"},{"key":"E","text":"<p>Faris mainly uses his headphones to reduce surrounding noise.</p>"}]'::jsonb, updated_at = now() where id = 'tka-eng01-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>AI sounds confident → distinguish low- and high-risk uses → verify important claims → test claims critically → learner remains responsible</p>"},{"key":"B","text":"<p>AI gives wrong dates → students should avoid AI → textbooks solve every disagreement → searching confirms the first answer</p>","misconceptionId":"mis-eng-sum-007"},{"key":"C","text":"<p>AI suggests titles → official pages are always correct → students compare writing styles → assignments become faster and easier</p>","misconceptionId":"mis-eng-sum-001"},{"key":"D","text":"<p>Students use AI daily → scientific studies are difficult → several sources may disagree → technology should replace manual checking</p>","misconceptionId":"mis-eng-sum-003"},{"key":"E","text":"<p>Reliable sources exist → students prefer confident answers → AI creates references → teachers should decide every factual question</p>","misconceptionId":"mis-eng-sum-010"}]'::jsonb, updated_at = now() where id = 'tka-eng02-auth-001';
update public.questions set options = '[{"key":"A","text":"<p>Generative AI can support early work, but students should identify important claims, verify them with reliable sources, and test evidence critically.</p>"},{"key":"B","text":"<p>Generative AI frequently invents dates and sources, so students should use textbooks instead whenever they complete assessed school assignments.</p>","misconceptionId":"mis-eng-sum-007"},{"key":"C","text":"<p>Students should compare official pages with textbooks because reliable sources usually provide exactly the same information about every topic.</p>","misconceptionId":"mis-eng-sum-003"},{"key":"D","text":"<p>The main benefit of generative AI is producing presentation titles, while factual questions should always be answered without using technology.</p>","misconceptionId":"mis-eng-sum-001"},{"key":"E","text":"<p>Verification means finding several online sentences that agree with an AI response before including that response in a school assignment.</p>","misconceptionId":"mis-eng-sum-003"}]'::jsonb, updated_at = now() where id = 'tka-eng02-auth-002';
update public.questions set statements = '[{"id":"A","text":"<p>Decide what the app is expected to do.</p>","correctCategoryKey":"purpose","misconceptionId":"mis-eng-sum-004"},{"id":"B","text":"<p>Examine requests for camera, microphone, contacts, files, or location.</p>","correctCategoryKey":"permissions","misconceptionId":"mis-eng-sum-004"},{"id":"C","text":"<p>Select the least broad access that still lets a feature work.</p>","correctCategoryKey":"setting","misconceptionId":"mis-eng-sum-004"},{"id":"D","text":"<p>Change permissions that prove unnecessary after using the app.</p>","correctCategoryKey":"review","misconceptionId":"mis-eng-sum-004"}]'::jsonb, updated_at = now() where id = 'tka-eng02-auth-003';
update public.questions set options = '[{"key":"A","text":"<p>Users should compare requested access with the app’s main purpose.</p>"},{"key":"B","text":"<p>A calculator is given as an example of an app that normally does not need location.</p>","misconceptionId":"mis-eng-sum-005"},{"key":"C","text":"<p>Users should choose the narrowest permission setting that still allows a needed feature.</p>"},{"key":"D","text":"<p>Permissions can be reviewed again after users understand how the app works.</p>"},{"key":"E","text":"<p>The routine guarantees complete privacy when all four steps are followed correctly.</p>","misconceptionId":"mis-eng-sum-007"}]'::jsonb, updated_at = now() where id = 'tka-eng02-auth-004';
update public.questions set options = '[{"key":"A","text":"<p>The class tested a voluntary phone-parking system and observed both its benefits and limitations.</p>"},{"key":"B","text":"<p>Several notification sounds came from phones that had not been silenced during the first part.</p>","misconceptionId":"mis-eng-sum-001"},{"key":"C","text":"<p>Exactly twenty-one of thirty-two students chose to place their phones in numbered pockets.</p>","misconceptionId":"mis-eng-sum-001"},{"key":"D","text":"<p>Two students collected their phones early because they were waiting for messages from family members.</p>","misconceptionId":"mis-eng-sum-010"},{"key":"E","text":"<p>Some students suggested placing phones face down on desks instead of using the numbered pockets.</p>","misconceptionId":"mis-eng-sum-010"}]'::jsonb, updated_at = now() where id = 'tka-eng02-auth-005';
update public.questions set options = '[{"key":"A","text":"<p>The experiment showed that separating phones may improve awareness and focus, but students still noticed other distractions and different access needs.</p>"},{"key":"B","text":"<p>The experiment proved that every class should keep phones in numbered pockets because most students became completely focused after the break.</p>","misconceptionId":"mis-eng-sum-007"},{"key":"C","text":"<p>The experiment failed because notification sounds distracted students and two participants needed to collect their phones before the session ended.</p>","misconceptionId":"mis-eng-sum-001"},{"key":"D","text":"<p>The experiment mainly showed that family messages are the most important reason students should always keep phones beside them in class.</p>","misconceptionId":"mis-eng-sum-001"},{"key":"E","text":"<p>The experiment demonstrated that conversations cause more distraction than phones and therefore should be controlled during every project session.</p>","misconceptionId":"mis-eng-sum-003"}]'::jsonb, updated_at = now() where id = 'tka-eng02-auth-006';
update public.questions set statements = '[{"id":"A","text":"<p>Fabric panels were installed above seating areas.</p>","correctCategoryKey":"shade","misconceptionId":"mis-eng-sum-010"},{"id":"B","text":"<p>Lighter removable tiles were tested against dark paving.</p>","correctCategoryKey":"surfaces","misconceptionId":"mis-eng-sum-010"},{"id":"C","text":"<p>Benches were moved closer to shaded locations.</p>","correctCategoryKey":"use","misconceptionId":"mis-eng-sum-010"},{"id":"D","text":"<p>Climbing vines were planted beside a frame.</p>","correctCategoryKey":"shade","misconceptionId":"mis-eng-sum-010"}]'::jsonb, updated_at = now() where id = 'tka-eng02-auth-007';
update public.questions set options = '[{"key":"A","text":"<p>The school tested several smaller changes because rebuilding the whole courtyard was not practical.</p>"},{"key":"B","text":"<p>The design included changes to shade, surfaces, and the way students used the courtyard.</p>"},{"key":"C","text":"<p>The original courtyard had dark paving and only a narrow roof protecting students from sunlight.</p>","misconceptionId":"mis-eng-sum-001"},{"key":"D","text":"<p>The team planned to use temperature records and student feedback before recommending further changes.</p>"},{"key":"E","text":"<p>The project was presented as a complete solution that would remove the effects of extreme heat.</p>","misconceptionId":"mis-eng-sum-007"}]'::jsonb, updated_at = now() where id = 'tka-eng02-auth-008';
update public.questions set options = '[{"key":"A","text":"<p>Compare an AI response with a textbook, official information page, or another reliable reference.</p>"},{"key":"B","text":"<p>Separate low-risk creative help from factual claims that can affect the accuracy of an assignment.</p>","misconceptionId":"mis-eng-sum-010"},{"key":"C","text":"<p>Test a claim by considering what evidence could show that the first AI answer is incorrect.</p>","misconceptionId":"mis-eng-sum-010"},{"key":"D","text":"<p>Recognize that reliable work still requires the learner to question, compare, and verify information.</p>","misconceptionId":"mis-eng-sum-010"},{"key":"E","text":"<p>Understand that confident language does not guarantee that an AI-generated factual answer is accurate.</p>","misconceptionId":"mis-eng-sum-010"}]'::jsonb, updated_at = now() where id = 'tka-eng02-auth-009';
update public.questions set options = '[{"key":"A","text":"<p>The school tested lighter tiles and compared their temperatures with the original dark paving on sunny days.</p>"},{"key":"B","text":"<p>A school tested affordable courtyard changes involving shade, surfaces, and space use before planning its next stage.</p>","misconceptionId":"mis-eng-sum-002"},{"key":"C","text":"<p>Students proposed practical courtyard changes and planned to evaluate them using measurements and user feedback.</p>","misconceptionId":"mis-eng-sum-009"},{"key":"D","text":"<p>The courtyard project tested several limited improvements instead of treating one redesign as a complete heat solution.</p>","misconceptionId":"mis-eng-sum-002"},{"key":"E","text":"<p>Within a limited budget, the school changed several courtyard features and collected evidence for future decisions.</p>","misconceptionId":"mis-eng-sum-009"}]'::jsonb, updated_at = now() where id = 'tka-eng02-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>AI can support explanations, but frequent use by itself does not show that a student is learning well.</p>"},{"key":"B","text":"<p>Students who use AI most frequently usually understand difficult lessons better than other students.</p>","misconceptionId":"mis-eng-syn-004"},{"key":"C","text":"<p>Rewriting every AI response is the only reliable way to prevent factual errors in school assignments.</p>","misconceptionId":"mis-eng-syn-005"},{"key":"D","text":"<p>Practice questions are more useful for learning than explanations or brainstorming activities.</p>","misconceptionId":"mis-eng-syn-007"},{"key":"E","text":"<p>Teachers should measure AI-assisted learning mainly by counting how many prompts students send.</p>","misconceptionId":"mis-eng-syn-008"}]'::jsonb, updated_at = now() where id = 'tka-eng03-auth-001';
update public.questions set options = '[{"key":"A","text":"<p>Students may value follow-up explanations, while useful study still requires them to examine the quality of AI responses.</p>"},{"key":"B","text":"<p>Because some students found incorrect details, AI should not be used for explanations or practice questions.</p>","misconceptionId":"mis-eng-syn-005"},{"key":"C","text":"<p>Checking factual claims and rewriting useful explanations can address different weaknesses in AI-assisted study.</p>"},{"key":"D","text":"<p>The survey proves that rewriting AI explanations in a student’s own words improves examination scores.</p>","misconceptionId":"mis-eng-syn-004"},{"key":"E","text":"<p>Both sources caution against treating the amount of AI use as a direct measure of successful learning.</p>"}]'::jsonb, updated_at = now() where id = 'tka-eng03-auth-002';
update public.questions set statements = '[{"id":"A","text":"<p>Students reported using AI to request simpler explanations.</p>","correctCategoryKey":"both","misconceptionId":"mis-eng-syn-006"},{"id":"B","text":"<p>Students should rewrite useful explanations in their own words.</p>","correctCategoryKey":"b","misconceptionId":"mis-eng-syn-006"},{"id":"C","text":"<p>The number of AI interactions should not be treated as proof of successful learning.</p>","correctCategoryKey":"both","misconceptionId":"mis-eng-syn-006"},{"id":"D","text":"<p>The survey recorded how many students used AI for several study tasks.</p>","correctCategoryKey":"a","misconceptionId":"mis-eng-syn-006"}]'::jsonb, updated_at = now() where id = 'tka-eng03-auth-003';
update public.questions set options = '[{"key":"A","text":"<p>Shade and surface conditions may affect comfort, but seating design and access to facilities can also influence where students spend time.</p>"},{"key":"B","text":"<p>The presence of mature trees is the only important reason students choose Area 2 during lunch on sunny days.</p>","misconceptionId":"mis-eng-syn-005"},{"key":"C","text":"<p>Area 1 is less popular because its air temperature is always much higher than the air temperature in Area 2.</p>","misconceptionId":"mis-eng-syn-004"},{"key":"D","text":"<p>Students mainly choose outdoor areas according to distance from the library rather than according to physical comfort.</p>","misconceptionId":"mis-eng-syn-007"},{"key":"E","text":"<p>Moving all benches into direct sunlight would allow the school to test whether seating arrangement matters more than shade.</p>","misconceptionId":"mis-eng-syn-008"}]'::jsonb, updated_at = now() where id = 'tka-eng03-auth-004';
update public.questions set options = '[{"key":"A","text":"<p>Shade is relevant to the school’s investigation of outdoor comfort and use.</p>"},{"key":"B","text":"<p>The available observations are enough to prove that trees alone cause students to choose Area 2.</p>","misconceptionId":"mis-eng-syn-004"},{"key":"C","text":"<p>The school would benefit from testing changes rather than assuming one factor explains every difference.</p>"},{"key":"D","text":"<p>Student use of the areas can be explained completely by measured surface temperature.</p>","misconceptionId":"mis-eng-syn-005"},{"key":"E","text":"<p>Physical conditions and features of the space should both be considered in future decisions.</p>"}]'::jsonb, updated_at = now() where id = 'tka-eng03-auth-005';
update public.questions set options = '[{"key":"A","text":"<p>Students’ reasons for choosing an area, including seating, nearby facilities, and preference for quiet.</p>"},{"key":"B","text":"<p>A comparison showing that dark paving can have a hotter surface than shaded ground.</p>","misconceptionId":"mis-eng-syn-006"},{"key":"C","text":"<p>A warning that the two areas differ in more than one physical feature.</p>","misconceptionId":"mis-eng-syn-006"},{"key":"D","text":"<p>An observation that Area 1 contains dark paving and has very little tree cover.</p>","misconceptionId":"mis-eng-syn-006"},{"key":"E","text":"<p>A statement that the existing observations should be treated as a starting point for further study.</p>","misconceptionId":"mis-eng-syn-006"}]'::jsonb, updated_at = now() where id = 'tka-eng03-auth-006';
update public.questions set options = '[{"key":"A","text":"<p>Students should identify which habits delay their planned sleep and test realistic changes instead of applying one identical phone rule to everyone.</p>"},{"key":"B","text":"<p>Students can solve most sleep problems by charging their phones away from the bed every night regardless of other scheduling pressures.</p>","misconceptionId":"mis-eng-syn-008"},{"key":"C","text":"<p>The diary proves that phone use during the final hour before bed directly causes students to feel tired the next morning.</p>","misconceptionId":"mis-eng-syn-004"},{"key":"D","text":"<p>Homework deadlines have little effect on bedtime compared with messaging, scrolling, and other forms of phone use.</p>","misconceptionId":"mis-eng-syn-007"},{"key":"E","text":"<p>A fixed bedtime routine is useful only when students completely avoid phones during the final hour of the evening.</p>","misconceptionId":"mis-eng-syn-005"}]'::jsonb, updated_at = now() where id = 'tka-eng03-auth-007';
update public.questions set options = '[{"key":"A","text":"<p>Personal records can help identify repeated bedtime habits that a student may choose to change.</p>"},{"key":"B","text":"<p>Phone-related changes are useful only if every student follows exactly the same stopping time.</p>","misconceptionId":"mis-eng-syn-005"},{"key":"C","text":"<p>Practical changes such as notification settings may help when phone habits are part of the problem.</p>"},{"key":"D","text":"<p>Other factors, such as late homework, may require a different change from simply adjusting the phone.</p>"},{"key":"E","text":"<p>A seven-day diary is sufficient to establish a scientific cause-and-effect relationship between phone use and sleep.</p>","misconceptionId":"mis-eng-syn-004"}]'::jsonb, updated_at = now() where id = 'tka-eng03-auth-008';
update public.questions set statements = '[{"id":"A","text":"<p>Late homework can also affect planned bedtime.</p>","correctCategoryKey":"shared","misconceptionId":"mis-eng-syn-006"},{"id":"B","text":"<p>Charge a phone away from the bed when phone use repeatedly delays sleep.</p>","correctCategoryKey":"action","misconceptionId":"mis-eng-syn-006"},{"id":"C","text":"<p>The pattern between phone use and bedtime was not identical for every student.</p>","correctCategoryKey":"observation","misconceptionId":"mis-eng-syn-006"},{"id":"D","text":"<p>Students should focus on realistic changes connected to their actual habits.</p>","correctCategoryKey":"shared","misconceptionId":"mis-eng-syn-006"}]'::jsonb, updated_at = now() where id = 'tka-eng03-auth-009';
update public.questions set options = '[{"key":"A","text":"<p>The claim is not supported because the survey did not measure academic effect, and both sources reject frequency alone as evidence of learning quality.</p>"},{"key":"B","text":"<p>The claim is supported because many students used AI for explanations, practice questions, and brainstorming during independent study.</p>","misconceptionId":"mis-eng-syn-004"},{"key":"C","text":"<p>The claim is supported only for students who rewrite AI explanations in their own words after every interaction with the tool.</p>","misconceptionId":"mis-eng-syn-005"},{"key":"D","text":"<p>The claim cannot be discussed because Source A describes students while Source B was written by teachers rather than by students.</p>","misconceptionId":"mis-eng-syn-006"},{"key":"E","text":"<p>The claim is incorrect mainly because students should use AI for generating titles rather than for understanding academic content.</p>","misconceptionId":"mis-eng-syn-010"}]'::jsonb, updated_at = now() where id = 'tka-eng03-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>Clear expectations about urgency and response time can reduce pressure while keeping group chats useful.</p>"},{"key":"B","text":"<p>Students should stop using project chats after 9 p.m. because late messages usually harm teamwork.</p>","misconceptionId":"mis-eng04-03"},{"key":"C","text":"<p>Digital communication problems mainly occur because students send too many messages during projects.</p>","misconceptionId":"mis-eng04-02"},{"key":"D","text":"<p>Urgent labels are valuable mainly because they greatly reduce the total number of messages.</p>","misconceptionId":"mis-eng04-02"},{"key":"E","text":"<p>Students feel response pressure only when another member officially demands an immediate reply.</p>","misconceptionId":"mis-eng04-10"}]'::jsonb, updated_at = now() where id = 'tka-eng04-auth-001';
update public.questions set options = '[{"key":"A","text":"<p>After the agreement, several students checked ordinary late-night messages less often before sleeping.</p>"},{"key":"B","text":"<p>Some members used several messaging applications for school, clubs, and family conversations.</p>","misconceptionId":"mis-eng04-07"},{"key":"C","text":"<p>Several students preferred typing messages to speaking during face-to-face project meetings.</p>","misconceptionId":"mis-eng04-07"},{"key":"D","text":"<p>One member changed the group-chat background shortly before the project was completed.</p>","misconceptionId":"mis-eng04-07"},{"key":"E","text":"<p>Students sometimes shared photographs and document files through the same messaging application.</p>","misconceptionId":"mis-eng04-07"}]'::jsonb, updated_at = now() where id = 'tka-eng04-auth-002';
update public.questions set options = '[{"key":"A","text":"<p>To explain how brief student recommendations can help readers notice books that might otherwise be overlooked.</p>"},{"key":"B","text":"<p>To persuade libraries to replace crowded shelves with rankings of their most popular books.</p>","misconceptionId":"mis-eng04-03"},{"key":"C","text":"<p>To show that graphic novels and science books are borrowed more often than other books.</p>","misconceptionId":"mis-eng04-05"},{"key":"D","text":"<p>To teach students to write long book reviews containing ratings and important plot endings.</p>","misconceptionId":"mis-eng04-05"},{"key":"E","text":"<p>To argue that displayed books should stay near the entrance until every student reads their cards.</p>","misconceptionId":"mis-eng04-03"}]'::jsonb, updated_at = now() where id = 'tka-eng04-auth-003';
update public.questions set options = '[{"key":"A","text":"<p>Several displayed books had received no loans for months before appearing near the entrance.</p>"},{"key":"B","text":"<p>Students often borrowed displayed older titles within days of reading the recommendation cards.</p>"},{"key":"C","text":"<p>The library also bought new chairs for a reading area during the same semester.</p>","misconceptionId":"mis-eng04-07"},{"key":"D","text":"<p>Some students later searched for other books by authors discovered through the display.</p>"},{"key":"E","text":"<p>The school library opens at the same time every weekday morning.</p>","misconceptionId":"mis-eng04-07"}]'::jsonb, updated_at = now() where id = 'tka-eng04-auth-004';
update public.questions set options = '[{"key":"A","text":"<p>A fair choice may require understanding how strongly the same resource is needed by different people.</p>"},{"key":"B","text":"<p>People should always surrender something they reach first whenever another person also wants it.</p>","misconceptionId":"mis-eng04-09"},{"key":"C","text":"<p>Online interviews are less important than portfolio work because interviews can happen at any table.</p>","misconceptionId":"mis-eng04-04"},{"key":"D","text":"<p>Shared study rooms work best when people avoid discussing why they need particular seats.</p>","misconceptionId":"mis-eng04-04"},{"key":"E","text":"<p>Good decisions are possible only when people have charged devices and noise-reducing headphones.</p>","misconceptionId":"mis-eng04-09"}]'::jsonb, updated_at = now() where id = 'tka-eng04-auth-005';
update public.questions set options = '[{"key":"A","text":"<p>Once the interview started, Raka answered each question without looking again toward the window table.</p>"},{"key":"B","text":"<p>The printer beside Raka produced several pages while another visitor waited near the door.</p>","misconceptionId":"mis-eng04-07"},{"key":"C","text":"<p>The girl’s folder contained printed pages, notes, and photographs for her portfolio.</p>","misconceptionId":"mis-eng04-07"},{"key":"D","text":"<p>Raka arrived early because buses to the community center were sometimes crowded.</p>","misconceptionId":"mis-eng04-07"},{"key":"E","text":"<p>The window table was popular because natural light reached it for much of the day.</p>","misconceptionId":"mis-eng04-08"}]'::jsonb, updated_at = now() where id = 'tka-eng04-auth-006';
update public.questions set options = '[{"key":"A","text":"<p>A chart can report accurate numbers and still be insufficient for a conclusion when important context is missing.</p>"},{"key":"B","text":"<p>Charts shared online are usually misleading because visual information makes readers ignore numerical data.</p>","misconceptionId":"mis-eng04-03"},{"key":"C","text":"<p>Readers should reject a chart whenever its source does not explain exactly why the numbers changed.</p>","misconceptionId":"mis-eng04-09"},{"key":"D","text":"<p>A percentage increase matters only when the original number was already large enough to attract attention.</p>","misconceptionId":"mis-eng04-10"},{"key":"E","text":"<p>Definitions are more important than data sources whenever readers evaluate information in a chart.</p>","misconceptionId":"mis-eng04-02"}]'::jsonb, updated_at = now() where id = 'tka-eng04-auth-007';
update public.questions set options = '[{"key":"A","text":"<p>The date the cycling route opened compared with the period shown in the chart.</p>"},{"key":"B","text":"<p>Whether weather conditions or unusual events changed during the measured month.</p>"},{"key":"C","text":"<p>Whether the same method counted bicycle trips before and after the increase.</p>"},{"key":"D","text":"<p>Which chart color received the most positive reactions from social-media viewers.</p>","misconceptionId":"mis-eng04-07"},{"key":"E","text":"<p>Whether the account had posted other charts about unrelated forms of transport.</p>","misconceptionId":"mis-eng04-07"}]'::jsonb, updated_at = now() where id = 'tka-eng04-auth-008';
update public.questions set options = '[{"key":"A","text":"<p>People who encounter charts in posts, articles, or other everyday information and want to judge them carefully.</p>"},{"key":"B","text":"<p>Professional statisticians who need instructions for building advanced mathematical models from raw data.</p>","misconceptionId":"mis-eng04-06"},{"key":"C","text":"<p>Town officials who already know exactly why bicycle use changed during the month shown.</p>","misconceptionId":"mis-eng04-06"},{"key":"D","text":"<p>Graphic designers who mainly need advice about choosing attractive colors for online charts.</p>","misconceptionId":"mis-eng04-06"},{"key":"E","text":"<p>Cyclists who want a detailed guide to selecting routes and maintaining bicycles safely.</p>","misconceptionId":"mis-eng04-06"}]'::jsonb, updated_at = now() where id = 'tka-eng04-auth-009';
update public.questions set options = '[{"key":"A","text":"<p>Small Recommendations, New Attention for Overlooked Books</p>"},{"key":"B","text":"<p>Why Every School Library Should Rank Its Most Popular Books</p>","misconceptionId":"mis-eng04-03"},{"key":"C","text":"<p>Six Students Explain How to Review Every New Library Book</p>","misconceptionId":"mis-eng04-02"},{"key":"D","text":"<p>Graphic Novels Become the Most Borrowed Books at School</p>","misconceptionId":"mis-eng04-02"},{"key":"E","text":"<p>Forty Words Are Enough to Reveal the Ending of Any Story</p>","misconceptionId":"mis-eng04-03"}]'::jsonb, updated_at = now() where id = 'tka-eng04-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>The council will review the pilot evidence before deciding whether and how to use the help desk at the event.</p>"},{"key":"B","text":"<p>The council will immediately open the help desk to every visitor because the third-day responses were shorter.</p>","misconceptionId":"mis-eng05-04"},{"key":"C","text":"<p>The volunteers will return to the first-day schedule file because it produced more detailed answers.</p>","misconceptionId":"mis-eng05-02"},{"key":"D","text":"<p>The school will cancel the event because some early answers contained outdated schedule information.</p>","misconceptionId":"mis-eng05-03"},{"key":"E","text":"<p>The council will replace all event signs with AI responses because location questions were answered well.</p>","misconceptionId":"mis-eng05-04"}]'::jsonb, updated_at = now() where id = 'tka-eng05-auth-001';
update public.questions set options = '[{"key":"A","text":"<p>Test initial answers → update information and uncertainty handling → shorten responses and observe access speed.</p>"},{"key":"B","text":"<p>Shorten responses → test initial answers → replace the schedule file → decide to launch the service.</p>","misconceptionId":"mis-eng05-02"},{"key":"C","text":"<p>Measure access speed → identify outdated information → recruit volunteers → rewrite location questions.</p>","misconceptionId":"mis-eng05-10"},{"key":"D","text":"<p>Launch the help desk → collect complaints → shorten the event schedule → test the system with volunteers.</p>","misconceptionId":"mis-eng05-02"},{"key":"E","text":"<p>Update the schedule → approve the help desk → identify unclear answers → begin the three-day pilot.</p>","misconceptionId":"mis-eng05-10"}]'::jsonb, updated_at = now() where id = 'tka-eng05-auth-002';
update public.questions set options = '[{"key":"A","text":"<p>Both use repeated review and adjust their method after noticing which part of their practice could improve.</p>"},{"key":"B","text":"<p>Both write every vocabulary item on paper before practising it in the original reading passage.</p>","misconceptionId":"mis-eng05-05"},{"key":"C","text":"<p>Both spend exactly fifteen minutes each evening reviewing the same number of difficult words.</p>","misconceptionId":"mis-eng05-05"},{"key":"D","text":"<p>Both believe creating original sentences is the fastest way to recognize vocabulary during a test.</p>","misconceptionId":"mis-eng05-06"},{"key":"E","text":"<p>Both conclude that their own review method should be used by every student preparing for a reading test.</p>","misconceptionId":"mis-eng05-08"}]'::jsonb, updated_at = now() where id = 'tka-eng05-auth-003';
update public.questions set options = '[{"key":"A","text":"<p>Nadia’s method keeps information visible together, while Bimo’s method separates words that need more attention.</p>"},{"key":"B","text":"<p>Bimo spends time creating his own examples, whereas Nadia uses an example sentence taken from the text.</p>"},{"key":"C","text":"<p>Nadia recognizes more target words than Bimo after one week because digital review is faster.</p>","misconceptionId":"mis-eng05-06"},{"key":"D","text":"<p>Bimo changes the order of items during practice, while Nadia reviews a digital list.</p>"},{"key":"E","text":"<p>Nadia prefers individual study, whereas Bimo can learn vocabulary only when working with other students.</p>","misconceptionId":"mis-eng05-08"}]'::jsonb, updated_at = now() where id = 'tka-eng05-auth-004';
update public.questions set options = '[{"key":"A","text":"<p>They will examine the four weeks of evidence and discuss whether a permanent station is practical and how it should operate.</p>"},{"key":"B","text":"<p>They will decide which food vendor should control the refill station because vendors supplied most of the drinking water.</p>","misconceptionId":"mis-eng05-03"},{"key":"C","text":"<p>They will remove the signs because visitors already know that every market drinking-water station is free.</p>","misconceptionId":"mis-eng05-04"},{"key":"D","text":"<p>They will end the market trial without reviewing the data because the lunchtime queue has already been solved.</p>","misconceptionId":"mis-eng05-01"},{"key":"E","text":"<p>They will require every visitor to bring a reusable bottle before entering the market on future Saturdays.</p>","misconceptionId":"mis-eng05-04"}]'::jsonb, updated_at = now() where id = 'tka-eng05-auth-005';
update public.questions set options = '[{"key":"A","text":"<p>Each week’s change responds to a problem noticed earlier, moving from visibility to message clarity and then crowd management.</p>"},{"key":"B","text":"<p>The organizers planned all changes before the trial and introduced them in random order to keep visitors interested.</p>","misconceptionId":"mis-eng05-10"},{"key":"C","text":"<p>The station became more difficult to find each week, so organizers gradually reduced the amount of information on signs.</p>","misconceptionId":"mis-eng05-06"},{"key":"D","text":"<p>Visitor comments were collected only after organizers had already decided to install a permanent refill station.</p>","misconceptionId":"mis-eng05-10"},{"key":"E","text":"<p>The queue line was introduced before the station became crowded because organizers expected lunchtime problems in advance.</p>","misconceptionId":"mis-eng05-02"}]'::jsonb, updated_at = now() where id = 'tka-eng05-auth-006';
update public.questions set options = '[{"key":"A","text":"<p>The Quiet Room mainly supports low-interruption individual work, while the Collaboration Corner supports discussion and shared tasks.</p>"},{"key":"B","text":"<p>The Quiet Room is designed only for examination candidates, while the Collaboration Corner is only for presentation teams.</p>","misconceptionId":"mis-eng05-08"},{"key":"C","text":"<p>The Quiet Room always has more available seats, while the Collaboration Corner is full throughout the entire day.</p>","misconceptionId":"mis-eng05-08"},{"key":"D","text":"<p>The Quiet Room has better furniture, while the Collaboration Corner is preferred because its equipment is newer.</p>","misconceptionId":"mis-eng05-09"},{"key":"E","text":"<p>The Quiet Room is intended for reading, while students are not allowed to read in the Collaboration Corner.</p>","misconceptionId":"mis-eng05-06"}]'::jsonb, updated_at = now() where id = 'tka-eng05-auth-007';
update public.questions set options = '[{"key":"A","text":"<p>Both areas can support study, although they are suited to different kinds of activity.</p>"},{"key":"B","text":"<p>A student may use both areas at different stages of work on the same material.</p>"},{"key":"C","text":"<p>Both areas can be used by a student working alone.</p>"},{"key":"D","text":"<p>Both areas provide the same level of protection from conversation and other interruptions.</p>","misconceptionId":"mis-eng05-06"},{"key":"E","text":"<p>Both areas become busiest at exactly the same time during examination season.</p>","misconceptionId":"mis-eng05-05"}]'::jsonb, updated_at = now() where id = 'tka-eng05-auth-008';
update public.questions set options = '[{"key":"A","text":"<p>Bimo already separates incorrectly answered words, while Nadia plans to add a similar way of highlighting difficult items.</p>"},{"key":"B","text":"<p>Nadia never notices difficult vocabulary, while Bimo immediately remembers every word placed in his separate pile.</p>","misconceptionId":"mis-eng05-08"},{"key":"C","text":"<p>Bimo identifies difficult words through classmates, while Nadia depends on automatic feedback from her digital list.</p>","misconceptionId":"mis-eng05-06"},{"key":"D","text":"<p>Nadia removes difficult words from review, while Bimo keeps only words he has already answered correctly.</p>","misconceptionId":"mis-eng05-06"},{"key":"E","text":"<p>Bimo’s system proves which words are objectively difficult for all students, while Nadia’s list measures only easy words.</p>","misconceptionId":"mis-eng05-08"}]'::jsonb, updated_at = now() where id = 'tka-eng05-auth-009';
update public.questions set options = '[{"key":"A","text":"<p>A student reads an article alone in the Quiet Room, then joins classmates in the Collaboration Corner to compare interpretations.</p>"},{"key":"B","text":"<p>The library removes the Collaboration Corner because students sometimes experience interruptions from nearby discussions.</p>","misconceptionId":"mis-eng05-03"},{"key":"C","text":"<p>A student demands that every group remain silent in the Collaboration Corner because the Quiet Room is already full.</p>","misconceptionId":"mis-eng05-01"},{"key":"D","text":"<p>The library ranks the Quiet Room above the Collaboration Corner after counting how many desks fill during examinations.</p>","misconceptionId":"mis-eng05-09"},{"key":"E","text":"<p>A student stops using the library because the two areas contain different furniture and follow different conversation rules.</p>","misconceptionId":"mis-eng05-01"}]'::jsonb, updated_at = now() where id = 'tka-eng05-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>They found that summaries could contain subtle errors that required checking against the original article.</p>"},{"key":"B","text":"<p>They discovered that the AI tool could not summarize long science articles unless students shortened them first.</p>","misconceptionId":"mis-eng06-04"},{"key":"C","text":"<p>They wanted to remove all AI use because preparing discussion notes had become faster than expected.</p>","misconceptionId":"mis-eng06-03"},{"key":"D","text":"<p>They learned that page references automatically prevented every disagreement during group discussions.</p>","misconceptionId":"mis-eng06-01"},{"key":"E","text":"<p>They preferred reading only numerical information because scientific explanations were not useful for meetings.</p>","misconceptionId":"mis-eng06-04"}]'::jsonb, updated_at = now() where id = 'tka-eng06-auth-001';
update public.questions set options = '[{"key":"A","text":"<p>Finding inaccurate or overstated claims led the group to verify important information against the source.</p>"},{"key":"B","text":"<p>Adding source references made it easier to resolve disagreements by locating relevant evidence.</p>"},{"key":"C","text":"<p>Using AI summaries caused students to stop reading original articles completely after several weeks.</p>","misconceptionId":"mis-eng06-01"},{"key":"D","text":"<p>The new checking routine made note preparation slightly longer than before.</p>"},{"key":"E","text":"<p>Longer preparation caused the AI system itself to become more accurate at generating summaries.</p>","misconceptionId":"mis-eng06-02"}]'::jsonb, updated_at = now() where id = 'tka-eng06-auth-002';
update public.questions set options = '[{"key":"A","text":"<p>She is becoming more reflective and willing to clarify criticism before defending her own decisions.</p>"},{"key":"B","text":"<p>She has become unwilling to explain any design choice because she now expects teammates to reject her work.</p>","misconceptionId":"mis-eng06-08"},{"key":"C","text":"<p>She believes every criticism is correct and should immediately replace her own judgment during group work.</p>","misconceptionId":"mis-eng06-08"},{"key":"D","text":"<p>She avoids difficult conversations by asking questions so that other people must make every project decision.</p>","misconceptionId":"mis-eng06-06"},{"key":"E","text":"<p>She is mainly concerned with finishing messages quickly, even when she does not understand the feedback.</p>","misconceptionId":"mis-eng06-07"}]'::jsonb, updated_at = now() where id = 'tka-eng06-auth-003';
update public.questions set options = '[{"key":"A","text":"<p>She listens to her defensive voice note, deletes it, and asks specific questions instead.</p>"},{"key":"B","text":"<p>She spends most of an evening designing presentation slides before receiving feedback.</p>","misconceptionId":"mis-eng06-06"},{"key":"C","text":"<p>She keeps most of the original visual style after reorganizing two sections of the presentation.</p>","misconceptionId":"mis-eng06-06"},{"key":"D","text":"<p>She notices that her partner sends screenshots showing two slides that are difficult to follow.</p>","misconceptionId":"mis-eng06-09"},{"key":"E","text":"<p>She receives another message from a teammate saying that the presentation ending still feels weak.</p>","misconceptionId":"mis-eng06-09"}]'::jsonb, updated_at = now() where id = 'tka-eng06-auth-004';
update public.questions set options = '[{"key":"A","text":"<p>They were trying to reduce exposure to direct sunlight and heat while crossing the courtyard.</p>"},{"key":"B","text":"<p>They believed the covered walkway was the shortest possible route to every classroom in the school.</p>","misconceptionId":"mis-eng06-04"},{"key":"C","text":"<p>Teachers had instructed all students to use the covered walkway during lunchtime on hot days.</p>","misconceptionId":"mis-eng06-04"},{"key":"D","text":"<p>The open courtyard had been officially closed because its paved surface was damaged by hot weather.</p>","misconceptionId":"mis-eng06-04"},{"key":"E","text":"<p>Students wanted to remain near the benches because the benches were cooler than every other area.</p>","misconceptionId":"mis-eng06-03"}]'::jsonb, updated_at = now() where id = 'tka-eng06-auth-005';
update public.questions set options = '[{"key":"A","text":"<p>The alternative route was also wider and benches were moved, so several changes could have influenced movement.</p>"},{"key":"B","text":"<p>The team discovered that students had never mentioned sunlight or surface heat during its observations.</p>","misconceptionId":"mis-eng06-04"},{"key":"C","text":"<p>The classroom entrances became more blocked after the alternative route received temporary shade.</p>","misconceptionId":"mis-eng06-02"},{"key":"D","text":"<p>The school removed the original covered walkway before enough students could compare the two routes.</p>","misconceptionId":"mis-eng06-04"},{"key":"E","text":"<p>The temporary shade changed the walking distance so much that earlier observations could no longer be used.</p>","misconceptionId":"mis-eng06-03"}]'::jsonb, updated_at = now() where id = 'tka-eng06-auth-006';
update public.questions set options = '[{"key":"A","text":"<p>He is responsible and privacy-conscious, trying to return the wallet without exposing unnecessary personal information.</p>"},{"key":"B","text":"<p>He is suspicious of everyone around him and assumes that any person at the bus stop may steal the wallet.</p>","misconceptionId":"mis-eng06-08"},{"key":"C","text":"<p>He is impatient and mainly wants the transport officer to solve the problem before his next bus arrives.</p>","misconceptionId":"mis-eng06-07"},{"key":"D","text":"<p>He is curious about other people’s possessions and uses lost objects as an opportunity to inspect private information.</p>","misconceptionId":"mis-eng06-06"},{"key":"E","text":"<p>He is unwilling to trust formal procedures and therefore personally decides whether the worried man owns the wallet.</p>","misconceptionId":"mis-eng06-09"}]'::jsonb, updated_at = now() where id = 'tka-eng06-auth-007';
update public.questions set options = '[{"key":"A","text":"<p>He avoids posting the identification card in a large neighborhood group after noticing the address on it.</p>"},{"key":"B","text":"<p>He asks whether staff will verify identity before giving a lost item to someone.</p>"},{"key":"C","text":"<p>He waits until the officer checks the claimant’s description and identification before boarding his bus.</p>"},{"key":"D","text":"<p>He notices that three other people are standing near the bus stop when he finds the wallet.</p>","misconceptionId":"mis-eng06-06"},{"key":"E","text":"<p>He smiles after the bus doors close even though he missed an earlier bus.</p>","misconceptionId":"mis-eng06-07"}]'::jsonb, updated_at = now() where id = 'tka-eng06-auth-008';
update public.questions set options = '[{"key":"A","text":"<p>Members could return to the relevant source passage when they disagreed about a claim.</p>"},{"key":"B","text":"<p>The AI tool stopped producing all numerical and interpretive errors in later summaries.</p>","misconceptionId":"mis-eng06-01"},{"key":"C","text":"<p>Students no longer needed to read the articles because every important point had a page number.</p>","misconceptionId":"mis-eng06-05"},{"key":"D","text":"<p>Meetings became shorter because members were no longer allowed to question shared notes.</p>","misconceptionId":"mis-eng06-04"},{"key":"E","text":"<p>The group could prepare its notes faster because checking the original articles was removed.</p>","misconceptionId":"mis-eng06-02"}]'::jsonb, updated_at = now() where id = 'tka-eng06-auth-009';
update public.questions set options = '[{"key":"A","text":"<p>She shifts from reacting defensively to asking for clarification before deciding how to respond.</p>"},{"key":"B","text":"<p>She shifts from enjoying design work to avoiding responsibility for every part of the presentation.</p>","misconceptionId":"mis-eng06-08"},{"key":"C","text":"<p>She shifts from trusting teammates completely to assuming that their feedback is usually inaccurate.</p>","misconceptionId":"mis-eng06-08"},{"key":"D","text":"<p>She shifts from asking detailed questions to sending immediate explanations whenever criticism appears.</p>","misconceptionId":"mis-eng06-02"},{"key":"E","text":"<p>She shifts from making independent decisions to accepting every suggestion without evaluating it.</p>","misconceptionId":"mis-eng06-10"}]'::jsonb, updated_at = now() where id = 'tka-eng06-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>An essay built from his real volunteering experiences, revised from his own rough notes before the deadline.</p>"},{"key":"B","text":"<p>The original AI draft unchanged because its formal style gives him the strongest chance of receiving the scholarship.</p>","misconceptionId":"mis-eng07-08"},{"key":"C","text":"<p>No application at all because writing from personal memories cannot be completed before a morning deadline.</p>","misconceptionId":"mis-eng07-01"},{"key":"D","text":"<p>A new essay claiming that he founded the reading program but using less formal language than the first draft.</p>","misconceptionId":"mis-eng07-04"},{"key":"E","text":"<p>A complaint asking the scholarship committee to remove the requirement that applicants write in their own voice.</p>","misconceptionId":"mis-eng07-05"}]'::jsonb, updated_at = now() where id = 'tka-eng07-auth-001';
update public.questions set options = '[{"key":"A","text":"<p>He will develop specific memories and remove claims that he cannot honestly support.</p>"},{"key":"B","text":"<p>He will add more impressive achievements so the new version sounds as polished as the AI draft.</p>","misconceptionId":"mis-eng07-04"},{"key":"C","text":"<p>He will stop using his own notes and copy only the longest paragraphs from the generated version.</p>","misconceptionId":"mis-eng07-08"},{"key":"D","text":"<p>He will change the scholarship instructions so that the generated text meets a different requirement.</p>","misconceptionId":"mis-eng07-05"},{"key":"E","text":"<p>He will replace the volunteering experience with an unrelated story that is easier for an AI tool to write.</p>","misconceptionId":"mis-eng07-06"}]'::jsonb, updated_at = now() where id = 'tka-eng07-auth-002';
update public.questions set options = '[{"key":"A","text":"<p>Sinta will take the blue-handled umbrella back and use her mother’s umbrella for her own walk.</p>"},{"key":"B","text":"<p>Sinta will keep the blue-handled umbrella because rain makes returning borrowed property unreasonable.</p>","misconceptionId":"mis-eng07-04"},{"key":"C","text":"<p>Sinta will post the owner’s name publicly because the administrator has already identified Lena.</p>","misconceptionId":"mis-eng07-05"},{"key":"D","text":"<p>Sinta will throw the umbrella away because it was mistakenly placed near the shared collection.</p>","misconceptionId":"mis-eng07-01"},{"key":"E","text":"<p>Sinta will wait several weeks to see whether Lena still remembers losing the umbrella.</p>","misconceptionId":"mis-eng07-06"}]'::jsonb, updated_at = now() where id = 'tka-eng07-auth-003';
update public.questions set options = '[{"key":"A","text":"<p>The administrator helps return the umbrella to Lena after Sinta brings it back.</p>"},{"key":"B","text":"<p>Sinta uses a different umbrella so that expected rain does not prevent her from returning Lena’s.</p>"},{"key":"C","text":"<p>Sinta deliberately removes Lena’s name so the umbrella can become part of the shared collection.</p>","misconceptionId":"mis-eng07-04"},{"key":"D","text":"<p>Sinta remembers the return because she placed the umbrella beside the bag she will take in the morning.</p>"},{"key":"E","text":"<p>The course permanently closes its umbrella collection because one personal umbrella was placed near it.</p>","misconceptionId":"mis-eng07-07"}]'::jsonb, updated_at = now() where id = 'tka-eng07-auth-004';
update public.questions set options = '[{"key":"A","text":"<p>They will compare the new sensor reading with the actual soil condition and record what they observe.</p>"},{"key":"B","text":"<p>They will water the garden immediately because every phone alert must be treated as accurate.</p>","misconceptionId":"mis-eng07-07"},{"key":"C","text":"<p>They will remove the sensor permanently before checking whether its new position changes the readings.</p>","misconceptionId":"mis-eng07-01"},{"key":"D","text":"<p>They will buy a more expensive sensor because the group has already proved that the current device is defective.</p>","misconceptionId":"mis-eng07-07"},{"key":"E","text":"<p>They will ignore both the sensor and the soil because the installation guide cannot help with garden decisions.</p>","misconceptionId":"mis-eng07-06"}]'::jsonb, updated_at = now() where id = 'tka-eng07-auth-005';
update public.questions set options = '[{"key":"A","text":"<p>They collect several days of comparison data before deciding whether the sensor needs replacement or only better placement.</p>"},{"key":"B","text":"<p>They conclude after one new reading that the sensor will always work perfectly in its new location.</p>","misconceptionId":"mis-eng07-07"},{"key":"C","text":"<p>Fajar secretly replaces the device so that Mei cannot continue checking the soil manually.</p>","misconceptionId":"mis-eng07-05"},{"key":"D","text":"<p>The group stops watering the garden because disagreement about the sensor makes plant care impossible.</p>","misconceptionId":"mis-eng07-01"},{"key":"E","text":"<p>They ask the phone application to choose a different garden because the raised bed is too difficult to measure.</p>","misconceptionId":"mis-eng07-05"}]'::jsonb, updated_at = now() where id = 'tka-eng07-auth-006';
update public.questions set options = '[{"key":"A","text":"<p>They will look for another repeated or less essential section to shorten while keeping the ending.</p>"},{"key":"B","text":"<p>They will submit the eight-minute-forty-second version because event time limits are usually optional.</p>","misconceptionId":"mis-eng07-06"},{"key":"C","text":"<p>They will restore the removed interview clip because Reno originally considered every clip important.</p>","misconceptionId":"mis-eng07-08"},{"key":"D","text":"<p>They will delete the ending because it is the fastest way to remove exactly forty seconds.</p>","misconceptionId":"mis-eng07-06"},{"key":"E","text":"<p>They will withdraw from the event because editing the recording further would change its original length.</p>","misconceptionId":"mis-eng07-01"}]'::jsonb, updated_at = now() where id = 'tka-eng07-auth-007';
update public.questions set options = '[{"key":"A","text":"<p>The event version reaches eight minutes after the team trims another nonessential section.</p>"},{"key":"B","text":"<p>The full eleven-minute version remains available for a different use, such as the school website.</p>"},{"key":"C","text":"<p>The team keeps the essential ending while shortening material elsewhere in the recording.</p>"},{"key":"D","text":"<p>Reno refuses all further editing and demands that the organizers change the time limit.</p>","misconceptionId":"mis-eng07-04"},{"key":"E","text":"<p>Maya deletes every interview clip because spoken material is the only reason the recording is too long.</p>","misconceptionId":"mis-eng07-07"}]'::jsonb, updated_at = now() where id = 'tka-eng07-auth-008';
update public.questions set options = '[{"key":"A","text":"<p>The group will have evidence that poor placement probably contributed to the earlier misleading readings.</p>"},{"key":"B","text":"<p>The group will have proved that low-cost sensors can never fail when installed near the center of a garden bed.</p>","misconceptionId":"mis-eng07-07"},{"key":"C","text":"<p>The group will know that rain had no effect on soil moisture during the first week of the project.</p>","misconceptionId":"mis-eng07-03"},{"key":"D","text":"<p>The volunteers will no longer need manual checks or observations under any future condition.</p>","misconceptionId":"mis-eng07-07"},{"key":"E","text":"<p>Fajar will have to leave the group because his earlier concern about a defective sensor was incorrect.</p>","misconceptionId":"mis-eng07-10"}]'::jsonb, updated_at = now() where id = 'tka-eng07-auth-009';
update public.questions set options = '[{"key":"A","text":"<p>He submits the unchanged AI draft, including claims he already knows are inaccurate, because it sounds impressive.</p>"},{"key":"B","text":"<p>He turns one real volunteering memory into the central example of a shorter personal essay.</p>","misconceptionId":"mis-eng07-03"},{"key":"C","text":"<p>He uses the generated draft only as a reference while rewriting unsupported parts in his own words.</p>","misconceptionId":"mis-eng07-08"},{"key":"D","text":"<p>He checks whether each important claim in the final essay matches something he actually experienced.</p>","misconceptionId":"mis-eng07-03"},{"key":"E","text":"<p>He accepts a less polished sentence when it describes his experience more accurately and personally.</p>","misconceptionId":"mis-eng07-10"}]'::jsonb, updated_at = now() where id = 'tka-eng07-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>The result came from one student while other study changes and differences between the tests could also explain the improvement.</p>"},{"key":"B","text":"<p>The later score cannot be factual because practice-test scores are always personal opinions rather than measurable results.</p>","misconceptionId":"mis-eng08-06"},{"key":"C","text":"<p>AI study tools cannot produce practice questions, so the student’s description of his revision method is unrealistic.</p>","misconceptionId":"mis-eng08-02"},{"key":"D","text":"<p>A score increase can be trusted only when the second test contains exactly twice as many questions as the first test.</p>","misconceptionId":"mis-eng08-08"},{"key":"E","text":"<p>The claim must be correct because increasing from 42 to 84 is a numerical change that can be shown in screenshots.</p>","misconceptionId":"mis-eng08-08"}]'::jsonb, updated_at = now() where id = 'tka-eng08-auth-001';
update public.questions set options = '[{"key":"A","text":"<p>The student’s two reported practice-test scores were 42 and 84.</p>"},{"key":"B","text":"<p>The student attended two tutoring sessions during the week between the tests.</p>"},{"key":"C","text":"<p>The two practice tests were not identical.</p>"},{"key":"D","text":"<p>Traditional revision is now outdated for students who can use AI.</p>","misconceptionId":"mis-eng08-05"},{"key":"E","text":"<p>The AI tool was responsible for most of the student’s score improvement.</p>","misconceptionId":"mis-eng08-05"}]'::jsonb, updated_at = now() where id = 'tka-eng08-auth-002';
update public.questions set options = '[{"key":"A","text":"<p>The robot stops when a bicycle blocks its route and continues after enough space becomes available.</p>"},{"key":"B","text":"<p>The robot understands the social habits of students better than people who have just arrived on campus.</p>","misconceptionId":"mis-eng08-03"},{"key":"C","text":"<p>The robot identifies every student personally and judges who deserves to receive an order first.</p>","misconceptionId":"mis-eng08-03"},{"key":"D","text":"<p>The robot predicts every future obstacle before beginning a delivery and therefore never needs to stop.</p>","misconceptionId":"mis-eng08-03"},{"key":"E","text":"<p>The robot decides independently that rain is unpleasant and cancels deliveries because it dislikes getting wet.</p>","misconceptionId":"mis-eng08-03"}]'::jsonb, updated_at = now() where id = 'tka-eng08-auth-003';
update public.questions set options = '[{"key":"A","text":"<p>The documented functions describe navigation and delivery operations, not personal recognition combined with social judgment.</p>"},{"key":"B","text":"<p>Any robot that moves on a pavement is fictional because autonomous machines can operate only inside buildings.</p>","misconceptionId":"mis-eng08-02"},{"key":"C","text":"<p>The claim is false simply because it appeared in a student post rather than on the campus service page.</p>","misconceptionId":"mis-eng08-07"},{"key":"D","text":"<p>A robot cannot make any automated decision unless a human operator controls every movement in real time.</p>","misconceptionId":"mis-eng08-02"},{"key":"E","text":"<p>The claim is probably true because delivery tracking requires the robot to know every customer’s personality.</p>","misconceptionId":"mis-eng08-03"}]'::jsonb, updated_at = now() where id = 'tka-eng08-auth-004';
update public.questions set options = '[{"key":"A","text":"<p>The club stated, “Phones Are Destroying School Conversation.”</p>"},{"key":"B","text":"<p>Fifty students participated in the one-week activity.</p>","misconceptionId":"mis-eng08-06"},{"key":"C","text":"<p>Thirty-six participants completed the short survey.</p>","misconceptionId":"mis-eng08-06"},{"key":"D","text":"<p>Twenty-four respondents reported speaking more with people at the table.</p>","misconceptionId":"mis-eng08-06"},{"key":"E","text":"<p>Four respondents said they preferred having access to their phones during lunch.</p>","misconceptionId":"mis-eng08-06"}]'::jsonb, updated_at = now() where id = 'tka-eng08-auth-005';
update public.questions set options = '[{"key":"A","text":"<p>The sample was self-selected, some participants did not respond, and the reported experiences were not the same for everyone.</p>"},{"key":"B","text":"<p>The trial lasted a full school week, which is too long for any survey result to remain valid.</p>","misconceptionId":"mis-eng08-09"},{"key":"C","text":"<p>The club used numbers in its report, so the conclusion should be treated as a factual statement rather than a claim.</p>","misconceptionId":"mis-eng08-08"},{"key":"D","text":"<p>The adviser suggested another trial, proving that none of the first survey responses can be considered real evidence.</p>","misconceptionId":"mis-eng08-02"},{"key":"E","text":"<p>Students placed phones in their own bags instead of giving them to teachers, making conversation impossible to measure.</p>","misconceptionId":"mis-eng08-04"}]'::jsonb, updated_at = now() where id = 'tka-eng08-auth-006';
update public.questions set options = '[{"key":"A","text":"<p>The automatic watering system released water according to its timer shortly before Nara came outside.</p>"},{"key":"B","text":"<p>The basil plants sensed that they were thirsty and activated the watering system by themselves.</p>","misconceptionId":"mis-eng08-03"},{"key":"C","text":"<p>The dry city weather produced a small private rain cloud directly above the apartment balcony.</p>","misconceptionId":"mis-eng08-01"},{"key":"D","text":"<p>The plants created water inside their leaves and moved enough of it into the surrounding soil.</p>","misconceptionId":"mis-eng08-03"},{"key":"E","text":"<p>The timer predicted Nara’s arrival and watered the plants because it knew she would inspect them.</p>","misconceptionId":"mis-eng08-03"}]'::jsonb, updated_at = now() where id = 'tka-eng08-auth-007';
update public.questions set options = '[{"key":"A","text":"<p>Their father had installed an automatic watering system before leaving.</p>"},{"key":"B","text":"<p>The timer was set to release water at 10:45 p.m.</p>"},{"key":"C","text":"<p>A wet patch appeared below one of the tube connections.</p>"},{"key":"D","text":"<p>Nara’s brother said that the plants knew when they were thirsty.</p>","misconceptionId":"mis-eng08-07"},{"key":"E","text":"<p>Nara jokingly wrote that the basil was taking care of itself.</p>","misconceptionId":"mis-eng08-10"}]'::jsonb, updated_at = now() where id = 'tka-eng08-auth-008';
update public.questions set options = '[{"key":"A","text":"<p>“Many Surveyed Volunteers Reported More Conversation During a Phone-Free Lunch Trial.”</p>"},{"key":"B","text":"<p>“Removing Phones Makes Every Student More Social During Every School Lunch.”</p>","misconceptionId":"mis-eng08-09"},{"key":"C","text":"<p>“New Study Proves That Phones Are the Main Cause of Weak Friendships at School.”</p>","misconceptionId":"mis-eng08-09"},{"key":"D","text":"<p>“Students No Longer Want Phones at Lunch After Successful School-Wide Experiment.”</p>","misconceptionId":"mis-eng08-09"},{"key":"E","text":"<p>“Phone-Free Lunch Is the Best Solution to All Communication Problems Among Teenagers.”</p>","misconceptionId":"mis-eng08-10"}]'::jsonb, updated_at = now() where id = 'tka-eng08-auth-009';
update public.questions set options = '[{"key":"A","text":"<p>Results from comparable learners using similar tests, with study conditions that allow the AI method to be meaningfully compared.</p>"},{"key":"B","text":"<p>More comments saying that the original short video felt motivating and looked convincing on a phone screen.</p>","misconceptionId":"mis-eng08-10"},{"key":"C","text":"<p>A longer caption repeating that the score doubled and describing traditional revision as old-fashioned.</p>","misconceptionId":"mis-eng08-10"},{"key":"D","text":"<p>Another screenshot of the same student’s score without information about the test or other study activities.</p>","misconceptionId":"mis-eng08-08"},{"key":"E","text":"<p>A statement from the AI tool explaining that its own practice questions are more effective than all other methods.</p>","misconceptionId":"mis-eng08-07"}]'::jsonb, updated_at = now() where id = 'tka-eng08-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>Both support positive perceptions among many respondents, but Source B challenges the claim that the survey proves better learning.</p>"},{"key":"B","text":"<p>Source B proves Source A is entirely false because teachers and students cannot produce valid information about the same workshop.</p>","misconceptionId":"mis-eng09-04"},{"key":"C","text":"<p>The sources fully confirm that AI improves achievement because both mention benefits reported after the workshop.</p>","misconceptionId":"mis-eng09-03"},{"key":"D","text":"<p>Source A is more valid because 72 responses are automatically stronger evidence than a written review by teachers.</p>","misconceptionId":"mis-eng09-06"},{"key":"E","text":"<p>Source B is irrelevant because it does not repeat the exact number of students who selected each questionnaire response.</p>","misconceptionId":"mis-eng09-09"}]'::jsonb, updated_at = now() where id = 'tka-eng09-auth-001';
update public.questions set options = '[{"key":"A","text":"<p>Comparable assessment results from students using AI-supported study and students using another study approach.</p>"},{"key":"B","text":"<p>More comments from workshop participants describing whether the AI interface looked modern and easy to use.</p>","misconceptionId":"mis-eng09-09"},{"key":"C","text":"<p>The total number of AI questions generated during the workshop, without information about student performance.</p>","misconceptionId":"mis-eng09-09"},{"key":"D","text":"<p>A longer council post explaining why its members personally believe AI tutoring will become popular.</p>","misconceptionId":"mis-eng09-02"},{"key":"E","text":"<p>The names of all students who completed the voluntary questionnaire after attending the workshop.</p>","misconceptionId":"mis-eng09-09"}]'::jsonb, updated_at = now() where id = 'tka-eng09-auth-002';
update public.questions set options = '[{"key":"A","text":"<p>Other conditions changed at the same time, while direct refill use and total single-use bottle waste were not measured.</p>"},{"key":"B","text":"<p>The decline is unusable because information expressed as weekly averages can never support an environmental conclusion.</p>","misconceptionId":"mis-eng09-06"},{"key":"C","text":"<p>The refill stations could not have affected bottle use because free reusable bottles were also distributed in January.</p>","misconceptionId":"mis-eng09-08"},{"key":"D","text":"<p>The newsletter is invalid because community centers are not allowed to report information about their own facilities.</p>","misconceptionId":"mis-eng09-02"},{"key":"E","text":"<p>The sales figures prove that exactly 160 fewer plastic bottles entered the waste stream every week in February.</p>","misconceptionId":"mis-eng09-08"}]'::jsonb, updated_at = now() where id = 'tka-eng09-auth-003';
update public.questions set options = '[{"key":"A","text":"<p>Counts of how often the refill stations were used during the period.</p>"},{"key":"B","text":"<p>Bottle-sales data from comparable weeks with normal café opening hours.</p>"},{"key":"C","text":"<p>Information about single-use bottles brought into the center from outside.</p>"},{"key":"D","text":"<p>The favorite colors of the reusable bottles distributed to members.</p>","misconceptionId":"mis-eng09-09"},{"key":"E","text":"<p>The names of the workers who installed each refill station.</p>","misconceptionId":"mis-eng09-09"}]'::jsonb, updated_at = now() where id = 'tka-eng09-auth-004';
update public.questions set options = '[{"key":"A","text":"<p>Tracking may support awareness, but the available evidence does not justify presenting one app as a guaranteed solution for teenagers’ sleep.</p>"},{"key":"B","text":"<p>The research proves that the student quoted in Source A did not become more disciplined after using the app.</p>","misconceptionId":"mis-eng09-07"},{"key":"C","text":"<p>Both sources prove that consumer sleep scores are as accurate as laboratory measurements for all stages of sleep.</p>","misconceptionId":"mis-eng09-03"},{"key":"D","text":"<p>The lifestyle article is fully validated because the research also mentions that tracking can increase awareness.</p>","misconceptionId":"mis-eng09-03"},{"key":"E","text":"<p>The research makes all consumer sleep trackers useless because some device estimates differed from laboratory measurements.</p>","misconceptionId":"mis-eng09-10"}]'::jsonb, updated_at = now() where id = 'tka-eng09-auth-005';
update public.questions set options = '[{"key":"A","text":"<p>The study examined different consumer trackers and young adults rather than the specific app and teenage users in the article.</p>"},{"key":"B","text":"<p>The study included 64 participants, so every finding from it must be less valid than one detailed personal story.</p>","misconceptionId":"mis-eng09-07"},{"key":"C","text":"<p>The research lasted four weeks, which means its measurements cannot be compared with any everyday sleep experience.</p>","misconceptionId":"mis-eng09-06"},{"key":"D","text":"<p>The study used laboratory measurements, making it unsuitable for evaluating the accuracy of consumer devices.</p>","misconceptionId":"mis-eng09-02"},{"key":"E","text":"<p>The researchers used cautious language, which shows they were uncertain about all observations collected in the study.</p>","misconceptionId":"mis-eng09-10"}]'::jsonb, updated_at = now() where id = 'tka-eng09-auth-006';
update public.questions set options = '[{"key":"A","text":"<p>Other activities used different measures, and the school has not defined which measure should determine overall success.</p>"},{"key":"B","text":"<p>Weight cannot be measured accurately for electronic waste because different devices have different shapes and materials.</p>","misconceptionId":"mis-eng09-06"},{"key":"C","text":"<p>The campaign cannot be successful unless every student in the school contributes at least one electronic item.</p>","misconceptionId":"mis-eng09-10"},{"key":"D","text":"<p>The number is invalid because environmental activities should be evaluated only by how enjoyable students find them.</p>","misconceptionId":"mis-eng09-09"},{"key":"E","text":"<p>The figure proves the campaign was the best because kilograms provide a more objective unit than any other measure.</p>","misconceptionId":"mis-eng09-05"}]'::jsonb, updated_at = now() where id = 'tka-eng09-auth-007';
update public.questions set options = '[{"key":"A","text":"<p>The 186-kilogram collection total has supporting evidence in the school records.</p>"},{"key":"B","text":"<p>The participation figure can describe one aspect of the campaign’s reach.</p>"},{"key":"C","text":"<p>The phrase “most successful” needs a clear definition of success before it can be compared across activities.</p>"},{"key":"D","text":"<p>The recorded weight proves that the campaign produced the greatest long-term behavior change among students.</p>","misconceptionId":"mis-eng09-08"},{"key":"E","text":"<p>Because the principal praised participation, every interpretation of the campaign’s success becomes equally valid.</p>","misconceptionId":"mis-eng09-02"}]'::jsonb, updated_at = now() where id = 'tka-eng09-auth-008';
update public.questions set options = '[{"key":"A","text":"<p>Many questionnaire respondents felt that the AI tools helped them identify topics needing further review.</p>"},{"key":"B","text":"<p>Most students at the school achieved higher test scores because they attended the optional AI workshop.</p>","misconceptionId":"mis-eng09-08"},{"key":"C","text":"<p>The workshop was equally effective for students who attended and students who chose not to participate.</p>","misconceptionId":"mis-eng09-01"},{"key":"D","text":"<p>The questionnaire accurately measured long-term learning gains for all 180 workshop participants.</p>","misconceptionId":"mis-eng09-05"},{"key":"E","text":"<p>Teachers concluded that AI tutoring should replace other exam-preparation approaches at the school.</p>","misconceptionId":"mis-eng09-10"}]'::jsonb, updated_at = now() where id = 'tka-eng09-auth-009';
update public.questions set options = '[{"key":"A","text":"<p>Define the criterion for success and determine how evidence from the different activities can be compared using that criterion.</p>"},{"key":"B","text":"<p>Convert every activity result into kilograms even when weight does not represent what the activity was designed to achieve.</p>","misconceptionId":"mis-eng09-05"},{"key":"C","text":"<p>Choose the activity with the largest numerical result because larger numbers always indicate stronger environmental impact.</p>","misconceptionId":"mis-eng09-06"},{"key":"D","text":"<p>Ask only the environmental club members which activity they liked most and use their preference as the final ranking.</p>","misconceptionId":"mis-eng09-07"},{"key":"E","text":"<p>Remove activities that used different measurements so the e-waste campaign remains the only activity being evaluated.</p>","misconceptionId":"mis-eng09-01"}]'::jsonb, updated_at = now() where id = 'tka-eng09-auth-010';
update public.questions set options = '[{"key":"A","text":"<p>King Hung Vuong VI wanted the best husband for his daughter.</p><p>Many princes came but none was suitable.</p><p>Son Tinh and Thuy Tinh both wanted to marry her.</p><p>The King gave them a test.</p><p>Thuy Tinh arrived first with the wedding gifts.</p><p>The princess was given to Thuy Tinh.</p>","misconceptionId":"mis-eng-sum-004"},{"key":"B","text":"<p>King Hung Vuong VI had a beautiful daughter.</p><p>He announced he was looking for the right husband.</p><p>Son Tinh and Thuy Tinh appeared and asked to marry her.</p><p>The King gave them a test with wedding gifts.</p><p>Son Tinh arrived first and married the princess.</p><p>Thuy Tinh attacked with floods but was defeated.</p>"},{"key":"C","text":"<p>King Hung Vuong VI asked his daughter to choose her husband.</p><p>The princess liked both Son Tinh and Thuy Tinh.</p><p>The King delayed his decision for many days.</p><p>Finally, he asked them to fight each other.</p><p>Thuy Tinh lost the battle and left the land.</p><p>The country never suffered from floods again.</p>","misconceptionId":"mis-eng-sum-004"},{"key":"D","text":"<p>King Hung Vuong VI searched for a husband for his daughter.</p><p>Son Tinh and Thuy Tinh wanted to marry her.</p><p>The King gave them a challenge.</p><p>Thuy Tinh lost the test and became angry.</p><p>He called the waters to rise and destroy the land.</p><p>Son Tinh drowned in the floods.</p>","misconceptionId":"mis-eng-sum-004"},{"key":"E","text":"<p>The King wanted a nobleman for his daughter.</p><p>He invited many princes to the palace.</p><p>Son Tinh and Thuy Tinh competed for the princess.</p><p>Son Tinh refused the challenge of gifts.</p><p>The King chose Thuy Tinh as the winner.</p><p>Thuy Tinh ruled peacefully without floods.</p>","misconceptionId":"mis-eng-sum-003"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-inggris-sma-001';
update public.questions set options = '[{"key":"A","text":"<p>He was jealous of Son Tinh’s victory</p>"},{"key":"B","text":"<p>He believed the King had lied to him.</p>","misconceptionId":"mis-eng06-04"},{"key":"C","text":"<p>He thought the princess loved him more.</p>","misconceptionId":"mis-eng06-04"},{"key":"D","text":"<p>He wanted to show off his power to the king.</p>","misconceptionId":"mis-eng06-06"},{"key":"E","text":"<p>He had promised to fight until death.</p>","misconceptionId":"mis-eng06-09"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-inggris-sma-002';
update public.questions set statements = '[{"id":"A","text":"<p>Both are not humans.</p>","correctCategoryKey":"similarity","misconceptionId":"mis-eng05-05"},{"id":"B","text":"<p>They can control the elements.</p>","correctCategoryKey":"similarity","misconceptionId":"mis-eng05-05"},{"id":"C","text":"<p>They love the king''s daughter.</p>","correctCategoryKey":"difference","misconceptionId":"mis-eng05-06"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-inggris-sma-003';
update public.questions set options = '[{"key":"A","text":"<p>Forgot about his decision. </p>","misconceptionId":"mis-eng-exp-009"},{"key":"B","text":"<p>Changed his mind about the wedding.</p>","misconceptionId":"mis-eng-exp-009"},{"key":"C","text":"<p>Did what he had promised to do.</p>"},{"key":"D","text":"<p>Delayed the marriage for many days.</p>","misconceptionId":"mis-eng-exp-002"},{"key":"E","text":"<p>The King asked the princes to bring more gifts.</p>","misconceptionId":"mis-eng-exp-004"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-inggris-sma-004';
update public.questions set options = '[{"key":"A","text":"<p>Accept defeat gracefully to prevent harm to others.</p>"},{"key":"B","text":"<p>Be fair and follow the agreed rules in competitions.</p>"},{"key":"C","text":"<p>Choose peaceful solutions rather than angry reactions.</p>","misconceptionId":"mis-eng04-04"},{"key":"D","text":"<p>Prepare honestly and present your gifts properly.</p>","misconceptionId":"mis-eng04-02"},{"key":"E","text":"<p>Respect leaders’ decisions and community agreements.</p>","misconceptionId":"mis-eng04-04"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-inggris-sma-005';
