update public.questions set options = '[{"key":"A","text":"<p>It has good lighting</p>"},{"key":"B","text":"<p>It provides white noise</p>","misconceptionId":"mis-eng-exp-004"},{"key":"C","text":"<p>It is located near the entrance</p>","misconceptionId":"mis-eng-exp-009"},{"key":"D","text":"<p>It is far from the toilet</p>"},{"key":"E","text":"<p>It provides stationery</p>","misconceptionId":"mis-eng-exp-004"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-inggris-sma-007';
update public.questions set options = '[{"key":"A","text":"<p>The students of that school</p>"},{"key":"B","text":"<p>People who happen to visit the school</p>","misconceptionId":"mis-eng04-06"},{"key":"C","text":"<p>The librarian of another school</p>","misconceptionId":"mis-eng04-06"},{"key":"D","text":"<p>The headmaster of that school</p>","misconceptionId":"mis-eng04-06"},{"key":"E","text":"<p>Parents who come to pick up their kids</p>","misconceptionId":"mis-eng04-06"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-inggris-sma-008';
