update public.questions set options = '[{"key":"A","text":"<p>A peaceful area filled with green forests, calm mangrove swamps, and colorful coral reefs along the sea.</p>"},{"key":"B","text":"<p>These terraces are shaped by generations of farmers who work the land by hand.</p>","misconceptionId":"mis-eng04-07"},{"key":"C","text":"<p>Water flows gently over rocky cliffs into a cool, clear pool. Mist rises into the air, mixing with the calming sound of falling water.</p>"},{"key":"D","text":"<p>In the morning, mist rises above the fields, and sunlight reflects off the water in the paddies.</p>"},{"key":"E","text":"<p>Farmers in wide-brimmed hats plant rice carefully, their feet sinking into the soft earth.</p>","misconceptionId":"mis-eng04-07"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-inggris-sma-013';
