update public.questions set options = '[{"key":"A","text":"<p>Research data showing the number of teenagers experiencing anxiety or depression because of social media.</p>"},{"key":"B","text":"<p>Personal stories from teenagers who feel happier after reducing their social media use.</p>"},{"key":"C","text":"<p>Statistics about how many teenagers use social media every day.</p>","misconceptionId":"mis-eng04-07"},{"key":"D","text":"<p>A list of the most popular social media platforms among teenagers.</p>","misconceptionId":"mis-eng04-07"},{"key":"E","text":"<p>Expert opinions from doctors or psychologists about the dangers of social media for mental health.</p>"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-inggris-sma-018';
update public.questions set options = '[{"key":"A","text":"<p>\"When teens see pictures of people who seem perfect, they feel that they are not good enough.\"</p>"},{"key":"B","text":"<p>\"Many teenagers use their phones late at night, which reduces sleep time and quality.\"</p>"},{"key":"C","text":"<p>\"Schools should teach students how to use social media in healthy ways.\"</p>","misconceptionId":"mis-eng04-07"},{"key":"D","text":"<p>\"Social media helps teens stay connected with friends and learn about interesting topics.\"</p>","misconceptionId":"mis-eng04-08"},{"key":"E","text":"<p>\"Victims of cyberbullying often feel alone, scared, and helpless.\"</p>"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-inggris-sma-019';
update public.questions set options = '[{"key":"A","text":"<p>Social media makes teenagers unhappy because they compare their lives to unrealistic images online.</p>"},{"key":"B","text":"<p>Teenagers should completely stop using social media to protect their mental health.</p>","misconceptionId":"mis-eng04-03"},{"key":"C","text":"<p>Using social media too much can disturb teenagers'' sleep and make it harder for them to focus at school.</p>"},{"key":"D","text":"<p>Cyberbullying is a serious problem on social media and can make teenagers feel lonely and scared.</p>"},{"key":"E","text":"<p>The text explains that social media has only negative effects without any positive sides.</p>","misconceptionId":"mis-eng04-03"}]'::jsonb, updated_at = now() where id = 'tka-bahasa-inggris-sma-020';

